-yogic-life-nocal-1366x768.jpg\" title=\"Urban Yogic Life - 1366x768\">1366x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-17/urban-yogic-life/nocal/june-17-urban-yogic-life-nocal-1400x1050.jpg\" title=\"Urban Yogic Life - 1400x1050\">1400x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-17/urban-yogic-life/nocal/june-17-urban-yogic-life-nocal-1440x900.jpg\" title=\"Urban Yogic Life - 1440x900\">1440x900</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-17/urban-yogic-life/nocal/june-17-urban-yogic-life-nocal-1600x1200.jpg\" title=\"Urban Yogic Life - 1600x1200\">1600x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-17/urban-yogic-life/nocal/june-17-urban-yogic-life-nocal-1680x1050.jpg\" title=\"Urban Yogic Life - 1680x1050\">1680x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-17/urban-yogic-life/nocal/june-17-urban-yogic-life-nocal-1680x1200.jpg\" title=\"Urban Yogic Life - 1680x1200\">1680x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-17/urban-yogic-life/nocal/june-17-urban-yogic-life-nocal-1920x1080.jpg\" title=\"Urban Yogic Life - 1920x1080\">1920x1080</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-17/urban-yogic-life/nocal/june-17-urban-yogic-life-nocal-1920x1200.jpg\" title=\"Urban Yogic Life - 1920x1200\">1920x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-17/urban-yogic-life/nocal/june-17-urban-yogic-life-nocal-1920x1440.jpg\" title=\"Urban Yogic Life - 1920x1440\">1920x1440</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-17/urban-yogic-life/nocal/june-17-urban-yogic-life-nocal-2560x1440.jpg\" title=\"Urban Yogic Life - 2560x1440\">2560x1440</a></li>\n</ul></p>\n\n<div class=\"sponsors__lead-place\"></div>\n\n\n\n\n<p><h4 id=\"summer-time\">Summer Time</h4><p>“Summer is coming so I made this simple pattern with all my favorite summer things.” — Designed by <a href=\"http://www.mariakellerac.com\">Maria Keller</a> from Mexico.</p>\n<figure class=\"break-out\"><a title=\"Summer Time\" href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/ce0197c0-f41c-4259-88c8-d1b2b4b7a4e9/june-16-summer-time-full-opt.png\"><img src=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/52cc4120-d654-47ad-88cc-c8b756bae675/june-16-summer-time-preview-opt.png\" alt=\"Summer Time\"></a></figure>\n<ul>\n<li><a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/52cc4120-d654-47ad-88cc-c8b756bae675/june-16-summer-time-preview-opt.png\" title=\"Summer Time - Preview\">preview</a></li>\n<li>without calendar: <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-320x480.png\" title=\"Summer Time - 320x480\">320x480</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-640x480.png\" title=\"Summer Time - 640x480\">640x480</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-640x1136.png\" title=\"Summer Time - 640x1136\">640x1136</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-750x1334.png\" title=\"Summer Time - 750x1334\">750x1334</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-800x480.png\" title=\"Summer Time - 800x480\">800x480</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-800x600.png\" title=\"Summer Time - 800x600\">800x600</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1024x768.png\" title=\"Summer Time - 1024x768\">1024x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1024x1024.png\" title=\"Summer Time - 1024x1024\">1024x1024</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1152x864.png\" title=\"Summer Time - 1152x864\">1152x864</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1242x2208.png\" title=\"Summer Time - 1242x2208\">1242x2208</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1280x720.png\" title=\"Summer Time - 1280x720\">1280x720</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1280x800.png\" title=\"Summer Time - 1280x800\">1280x800</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1280x960.png\" title=\"Summer Time - 1280x960\">1280x960</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1280x1024.png\" title=\"Summer Time - 1280x1024\">1280x1024</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1366x768.png\" title=\"Summer Time - 1366x768\">1366x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1400x1050.png\" title=\"Summer Time - 1400x1050\">1400x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1440x900.png\" title=\"Summer Time - 1440x900\">1440x900</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1600x1200.png\" title=\"Summer Time - 1600x1200\">1600x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1680x1050.png\" title=\"Summer Time - 1680x1050\">1680x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1680x1200.png\" title=\"Summer Time - 1680x1200\">1680x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1920x1080.png\" title=\"Summer Time - 1920x1080\">1920x1080</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1920x1200.png\" title=\"Summer Time - 1920x1200\">1920x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-1920x1440.png\" title=\"Summer Time - 1920x1440\">1920x1440</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-2560x1440.png\" title=\"Summer Time - 2560x1440\">2560x1440</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/summer-time/nocal/june-16-summer-time-nocal-2880x1800.png\" title=\"Summer Time - 2880x1800\">2880x1800</a></li>\n</ul></p>\n\n<p><h4 id=\"the-call-of-koel\">The Call Of Koel</h4><p>“The peak of summer is upon us, and June brings scorching heat to most places in India. Summer season in my state also reminds me of the bird songs, especially the Koel bird. A black bird with a red eye, this bird’s elegant voice rings through the trees on hot summer afternoons. This June, I have created a wallpaper to give life to this experience — the birds singing in scorching heat give us some respite!” — Designed by <a href=\"http://www.anujakanani.com/\">Anuja</a> from India.</p>\n<figure class=\"break-out\"><a title=\"The Call Of Koel\" href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/137857f9-d8cd-4567-99ab-ab4997fa0264/june-16-the-call-of-koel-full-opt.png\"><img src=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/66d08e59-c56c-4ae7-ad72-c8fabbf83be3/june-16-the-call-of-koel-preview-opt.png\" alt=\"The Call Of Koel\"></a></figure>\n<ul>\n<li><a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/66d08e59-c56c-4ae7-ad72-c8fabbf83be3/june-16-the-call-of-koel-preview-opt.png\" title=\"The Call Of Koel - Preview\">preview</a></li>\n<li>without calendar: <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/the-call-of-koel/nocal/june-16-the-call-of-koel-nocal-640x480.png\" title=\"The Call Of Koel - 640x480\">640x480</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/the-call-of-koel/nocal/june-16-the-call-of-koel-nocal-1024x768.png\" title=\"The Call Of Koel - 1024x768\">1024x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/the-call-of-koel/nocal/june-16-the-call-of-koel-nocal-1280x960.png\" title=\"The Call Of Koel - 1280x960\">1280x960</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/the-call-of-koel/nocal/june-16-the-call-of-koel-nocal-1366x768.png\" title=\"The Call Of Koel - 1366x768\">1366x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/the-call-of-koel/nocal/june-16-the-call-of-koel-nocal-1440x900.png\" title=\"The Call Of Koel - 1440x900\">1440x900</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/the-call-of-koel/nocal/june-16-the-call-of-koel-nocal-1680x1200.png\" title=\"The Call Of Koel - 1680x1200\">1680x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/the-call-of-koel/nocal/june-16-the-call-of-koel-nocal-1920x1080.png\" title=\"The Call Of Koel - 1920x1080\">1920x1080</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/the-call-of-koel/nocal/june-16-the-call-of-koel-nocal-1920x1200.png\" title=\"The Call Of Koel - 1920x1200\">1920x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/the-call-of-koel/nocal/june-16-the-call-of-koel-nocal-1920x1440.png\" title=\"The Call Of Koel - 1920x1440\">1920x1440</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/the-call-of-koel/nocal/june-16-the-call-of-koel-nocal-2560x1440.png\" title=\"The Call Of Koel - 2560x1440\">2560x1440</a></li>\n</ul></p>\n\n<p><h4 id=\"oh-the-places-you-will-go\">Oh, The Places You Will Go!</h4><p>“In celebration of high school and college graduates ready to make their way in the world!” — Designed by <a href=\"http://bloeschcreative.etsy.com\">Bri Loesch</a> from the United States.</p>\n<figure class=\"break-out\"><a title=\"Oh the places you will go\" href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/46f6cae6-a2aa-468c-ba2f-ecf40e375055/june-14-oh-the-places-you-will-go-full-opt.png\"><img src=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/5f1235cf-2e90-4379-9126-fb1afcc0338c/june-14-oh-the-places-you-will-go-preview-opt.png\" alt=\"Oh the places you will go\"></a></figure>\n<ul>\n<li><a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/5f1235cf-2e90-4379-9126-fb1afcc0338c/june-14-oh-the-places-you-will-go-preview-opt.png\" title=\"Oh the places you will go - Preview\">preview</a></li>\n<li>without calendar: <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/oh-the-places-you-will-go/nocal/june-14-oh-the-places-you-will-go-nocal-320x480.png\" title=\"Oh the places you will go - 320x480\">320x480</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/oh-the-places-you-will-go/nocal/june-14-oh-the-places-you-will-go-nocal-1024x768.png\" title=\"Oh the places you will go - 1024x768\">1024x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/oh-the-places-you-will-go/nocal/june-14-oh-the-places-you-will-go-nocal-1280x1024.png\" title=\"Oh the places you will go - 1280x1024\">1280x1024</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/oh-the-places-you-will-go/nocal/june-14-oh-the-places-you-will-go-nocal-1440x900.png\" title=\"Oh the places you will go - 1440x900\">1440x900</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/oh-the-places-you-will-go/nocal/june-14-oh-the-places-you-will-go-nocal-1680x1050.png\" title=\"Oh the places you will go - 1680x1050\">1680x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/oh-the-places-you-will-go/nocal/june-14-oh-the-places-you-will-go-nocal-1680x1200.png\" title=\"Oh the places you will go - 1680x1200\">1680x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/oh-the-places-you-will-go/nocal/june-14-oh-the-places-you-will-go-nocal-1920x1440.png\" title=\"Oh the places you will go - 1920x1440\">1920x1440</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/oh-the-places-you-will-go/nocal/june-14-oh-the-places-you-will-go-nocal-2560x1440.png\" title=\"Oh the places you will go - 2560x1440\">2560x1440</a></li></ul></p>\n\n<p><h4 id=\"almost-summer\">Almost Summer</h4><p>Designed by <a href=\"http://apartment406designs.com\">Mirjana Teuner</a> from Germany.</p>\n<figure class=\"break-out\"><a title=\"Almost Summer\" href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/edcdccd9-c7b8-480e-a93b-51cac94ff7b7/june-16-almost-summer-full-opt.png\"><img src=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/6fb71fe1-7c82-47a4-becd-bac559d0c853/june-16-almost-summer-preview-opt.png\" alt=\"Almost Summer\"></a></figure>\n<ul>\n<li><a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/6fb71fe1-7c82-47a4-becd-bac559d0c853/june-16-almost-summer-preview-opt.png\" title=\"Almost Summer - Preview\">preview</a></li>\n<li>without calendar: <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1280x720.png\" title=\"Almost Summer - 1280x720\">1280x720</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1280x800.png\" title=\"Almost Summer - 1280x800\">1280x800</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1280x960.png\" title=\"Almost Summer - 1280x960\">1280x960</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1280x1024.png\" title=\"Almost Summer - 1280x1024\">1280x1024</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1366x768.png\" title=\"Almost Summer - 1366x768\">1366x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1400x1050.png\" title=\"Almost Summer - 1400x1050\">1400x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1440x900.png\" title=\"Almost Summer - 1440x900\">1440x900</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1600x1200.png\" title=\"Almost Summer - 1600x1200\">1600x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1680x1050.png\" title=\"Almost Summer - 1680x1050\">1680x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1680x1200.png\" title=\"Almost Summer - 1680x1200\">1680x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1920x1080.png\" title=\"Almost Summer - 1920x1080\">1920x1080</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1920x1200.png\" title=\"Almost Summer - 1920x1200\">1920x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-1920x1440.png\" title=\"Almost Summer - 1920x1440\">1920x1440</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-16/almost-summer/nocal/june-16-almost-summer-nocal-2560x1440.png\" title=\"Almost Summer - 2560x1440\">2560x1440</a></li>\n</ul></p>\n\n<p><h4 id=\"knitting-for-summer\">Knitting For Summer</h4><p>“I made multiple circles overlapping with close distances. The overall drawing looks like a clothing texture, for something you could wear in coming summer. Let’s have a nice summer.” — Designed by Philippe Brouard from France.</p>\n<figure class=\"break-out\"><a title=\"Knitting For Summer\" href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/802471bb-946e-48f7-afad-4cb876048850/june-15-knitting-for-summer-full-opt.png\"><img src=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/719bb7b5-c3c9-4a23-ada6-a033f273c6ba/june-15-knitting-for-summer-preview-opt.png\" alt=\"Knitting For Summer\"></a></figure>\n<ul>\n<li><a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/719bb7b5-c3c9-4a23-ada6-a033f273c6ba/june-15-knitting-for-summer-preview-opt.png\" title=\"Knitting For Summer - Preview\">preview</a></li>\n<li>without calendar: <a href=\"http://files.smashingmagazine.com/wallpapers/june-15/knitting-for-summer/nocal/june-15-knitting-for-summer-nocal-800x480.jpg\" title=\"Knitting For Summer - 800x480\">800x480</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-15/knitting-for-summer/nocal/june-15-knitting-for-summer-nocal-1024x768.jpg\" title=\"Knitting For Summer - 1024x768\">1024x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-15/knitting-for-summer/nocal/june-15-knitting-for-summer-nocal-1280x720.jpg\" title=\"Knitting For Summer - 1280x720\">1280x720</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-15/knitting-for-summer/nocal/june-15-knitting-for-summer-nocal-1280x800.jpg\" title=\"Knitting For Summer - 1280x800\">1280x800</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-15/knitting-for-summer/nocal/june-15-knitting-for-summer-nocal-1440x900.jpg\" title=\"Knitting For Summer - 1440x900\">1440x900</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-15/knitting-for-summer/nocal/june-15-knitting-for-summer-nocal-1600x1200.jpg\" title=\"Knitting For Summer - 1600x1200\">1600x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-15/knitting-for-summer/nocal/june-15-knitting-for-summer-nocal-1920x1080.jpg\" title=\"Knitting For Summer - 1920x1080\">1920x1080</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-15/knitting-for-summer/nocal/june-15-knitting-for-summer-nocal-1920x1200.jpg\" title=\"Knitting For Summer - 1920x1200\">1920x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-15/knitting-for-summer/nocal/june-15-knitting-for-summer-nocal-2560x1440.jpg\" title=\"Knitting For Summer - 2560x1440\">2560x1440</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-15/knitting-for-summer/nocal/june-15-knitting-for-summer-nocal-2880x1800.jpg\" title=\"Knitting For Summer - 2880x1800\">2880x1800</a></li>\n</ul></p>\n\n<p><h4 id=\"camomile\">Camomile</h4><p>Designed by <a href=\"http://gatovision.pl\">Gato Vision</a> from Poland.</p>\n<figure class=\"break-out\"><a title=\"Camomile\" href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/9c85c9de-fd17-4a50-a467-6c9312319225/june-14-camomile-full-opt.png\"><img src=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/96a57c25-9241-4c4e-887d-291322fee6aa/june-14-camomile-preview-opt.png\" alt=\"Camomile\"></a></figure>\n<ul>\n<li><a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/96a57c25-9241-4c4e-887d-291322fee6aa/june-14-camomile-preview-opt.png\" title=\"Camomile - Preview\">preview</a></li>\n<li>without calendar: <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-320x480.jpg\" title=\"Camomile - 320x480\">320x480</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-640x480.jpg\" title=\"Camomile - 640x480\">640x480</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-800x480.jpg\" title=\"Camomile - 800x480\">800x480</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-800x600.jpg\" title=\"Camomile - 800x600\">800x600</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1024x768.jpg\" title=\"Camomile - 1024x768\">1024x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1152x864.jpg\" title=\"Camomile - 1152x864\">1152x864</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1280x720.jpg\" title=\"Camomile - 1280x720\">1280x720</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1280x800.jpg\" title=\"Camomile - 1280x800\">1280x800</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1280x960.jpg\" title=\"Camomile - 1280x960\">1280x960</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1280x1024.jpg\" title=\"Camomile - 1280x1024\">1280x1024</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1440x900.jpg\" title=\"Camomile - 1440x900\">1440x900</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1600x1200.jpg\" title=\"Camomile - 1600x1200\">1600x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1680x1050.jpg\" title=\"Camomile - 1680x1050\">1680x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1680x1200.jpg\" title=\"Camomile - 1680x1200\">1680x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1920x1080.jpg\" title=\"Camomile - 1920x1080\">1920x1080</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1920x1200.jpg\" title=\"Camomile - 1920x1200\">1920x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-1920x1440.jpg\" title=\"Camomile - 1920x1440\">1920x1440</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-14/camomile/nocal/june-14-camomile-nocal-2560x1440.jpg\" title=\"Camomile - 2560x1440\">2560x1440</a></li>\n</ul></p>\n\n<p><h4 id=\"digitalized-love-typography-sketch\">Digitalized Love Typography Sketch</h4><p>“Digging through my old sketches, I found this one I had almost forgotten about&hellip; With a little help from <a href=\"http://ricardogimenes.com/\">Ricardo</a>, the sketch was brought to life in a jiffy! Hope you like it.” — Designed by <a href=\"https://twitter.com/smash_it_on\">Iris Lješnjanin</a> from Freiburg, Germany</p>\n<figure class=\"break-out\"><a title=\"Digitalized Love Typography Sketch\" href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/81ffcca8-1b59-46b6-b4fd-f116b5a1b4e3/jun-13-love-typography-full-opt.png\"><img src=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/04658929-2e82-4765-b90f-a62616904140/jun-13-love-typography-preview-opt.png\" alt=\"Digitalized Love Typography Sketch\"></a></figure>\n<ul>\n<li><a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/04658929-2e82-4765-b90f-a62616904140/jun-13-love-typography-preview-opt.png\" title=\"Digitalized Love Typography Sketch - Preview\">preview</a></li>\n<li>without calendar: <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-320x480.png\" title=\"Digitalized Love Typography Sketch - 320x480\">320x480</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-640x960.png\" title=\"Digitalized Love Typography Sketch - 640x960\">640x960</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1024x768.png\" title=\"Digitalized Love Typography Sketch - 1024x768\">1024x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1024x1024.png\" title=\"Digitalized Love Typography Sketch - 1024x1024\">1024x1024</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1280x800.png\" title=\"Digitalized Love Typography Sketch - 1280x800\">1280x800</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1280x960.png\" title=\"Digitalized Love Typography Sketch - 1280x960\">1280x960</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1280x1024.png\" title=\"Digitalized Love Typography Sketch - 1280x1024\">1280x1024</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1366x768.png\" title=\"Digitalized Love Typography Sketch - 1366x768\">1366x768</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1400x1050.png\" title=\"Digitalized Love Typography Sketch - 1400x1050\">1400x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1440x900.png\" title=\"Digitalized Love Typography Sketch - 1440x900\">1440x900</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1600x1050.png\" title=\"Digitalized Love Typography Sketch - 1600x1050\">1600x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1600x1200.png\" title=\"Digitalized Love Typography Sketch - 1600x1200\">1600x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1680x1050.png\" title=\"Digitalized Love Typography Sketch - 1680x1050\">1680x1050</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1680x1200.png\" title=\"Digitalized Love Typography Sketch - 1680x1200\">1680x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1920x1080.png\" title=\"Digitalized Love Typography Sketch - 1920x1080\">1920x1080</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1920x1200.png\" title=\"Digitalized Love Typography Sketch - 1920x1200\">1920x1200</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-1920x1440.png\" title=\"Digitalized Love Typography Sketch - 1920x1440\">1920x1440</a>, <a href=\"http://files.smashingmagazine.com/wallpapers/june-13/digitalized-love-typography-sketch/jun-13-love-typography-nocal-2560x1440.png\" title=\"Digitalized Love Typography Sketch - 2560x1440\">2560x1440</a></li>\n</ul></p>\n\n<h3>Join In Next Month!</h3>\n\n<p>Please note that we respect and carefully consider the ideas and motivation behind each and every artist’s work. This is why we give all artists the <strong>full freedom to explore their creativity</strong> and express emotions and experience throughout their works. This is also why the themes of the wallpapers weren’t anyhow influenced by us but rather designed from scratch by the artists themselves.</p>\n\n<p>Thank you to all designers for their participation. <a href=\"https://www.smashingmagazine.com/desktop-wallpaper-calendars-join-in/\">Join in</a> next month!</p>\n\n\n	<div class=\"promo-newsletter--newsletter promo-newsletter--article\">\n    <div class=\"meow__content--inlined\">\n      \n\n<div class=\" promo-newsletter--newsletter\">\n\n<div class=\"promo-newsletter\">\n<div class=\"promo-newsletter-image-wrapper\">\n  <a href=\"/the-smashing-newsletter/\" class=\"promo-newsletter-image-link\">\n    <img src=\"/images/smashing-cat/cat-with-slippers.svg\" width=\"180\" height=\"235\" loading=\"lazy\" class=\"promo-newsletter-image\" alt=\"With Smashing Newsletter, it always feels like home. A cat with slippers reading the newsletter edition.\"/>\n  </a>\n</div>\n<h2 class=\"h2 promo-newsletter-title\">Smashing Newsletter</h2>\n<p class=\"promo-newsletter-description\">Every second Tuesday, we send a <a href=\"https://www.smashingmagazine.com/the-smashing-newsletter/\">newsletter</a> with useful techniques on front-end and UX. Subscribe and get <strong>Smart Interface Design Checklists PDF</strong> in your inbox.</p>\n\n<div class=\"promo-newsletter-form-wrapper\">\n  <div class=\"nl__form-wrapper\">\n  <form method=\"POST\" action=\"//smashingmagazine.us1.list-manage.com/subscribe/post?u=16b832d9ad4b28edf261f34df&amp;id=a1666656e0\" class=\"nl__form\">\n    <div class=\"input-wrapper \">\n      <label for=\"email\" class=\"form__field js-form-field form__field--floating nl__form__content \">\n        <span class=\"form__field__label\">Your <span class=\"form__field__label--extra\">(smashing)</span> email</span>\n        <input autocomplete=\"off\" class=\"form__field__input \" type=\"email\" pattern=\"(.+)@(.+){2,}\\.(.+){2,}\" name=\"EMAIL\" id=\"email\" required/>\n      </label>\n      <button\n      data-event-category=\"Button\"\n      data-event-action=\"click\"\n      data-event-label=\"Newsletter Box\"\n      type=\"submit\"\n      class=\"btn btn--medium  btn--green btn--promo-newsletter   ladda-button ladda-button--fixed\"\n      data-style=\"expand-right\"\n			onclick=\"this.form && this.form.submit()\"\n			value=\"Submit\"\n			>\n        <span class=\"ladda-label\">\nSubscribe <span class=\"nl__form__arrow\">→</span>\n          <wbr></span>\n          <span class=\"ladda-spinner\"></span>\n        </button>\n      </div>\n    </form>\n  </div>\n</div>\n\n  <small class=\"promo-newsletter-caption\">\n  Front-end, design and UX. Sent 2× a month. <br/>You can always unsubscribe with just one click.</small>\n\n</div>\n</div>\n    </div>\n  </div>\n    \n\n              </article>\n            </body>\n          </html>\n        ', 'Recent content in Articles on Smashing Magazine — For Web Designers And Developers', 'basic_html');
INSERT INTO `node__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('feed_rss', 0, 1008, 1008, 'en', 0, '\n<p>You can <a href=\"https://css-tricks.com/stripes-css/\">create stripes in CSS</a>. That’s all I thought about in terms of CSS background patterns for a long time. There’s nothing wrong with stripes; stripes are cool. They can be customized into wide and narrow bands, criss-crossed into a checked pattern, and played with in other ways using <a href=\"https://css-tricks.com/books/greatest-css-tricks/hard-stop-gradients/\">the idea of hard stops</a>. But stripes can be boring, too. Too conventional, out of fashion, and sometimes even unpleasant.</p>\n\n\n\n<p>Thankfully, we can conjure up far more background patterns than you can even imagine with CSS, with code that is similar in spirit to stripes.</p>\n\n\n\n<span id=\"more-312443\"></span>\n\n\n\n<p>Background patterns are images repeated across a background. They can be done by referencing an external image, like a PNG file, or can be drawn with CSS, which is traditionally done using CSS gradients.&nbsp;</p>\n\n\n\n<p><a href=\"https://css-tricks.com/snippets/css/css-linear-gradient/\">Linear gradients</a> (and <a href=\"https://css-tricks.com/snippets/css/css-repeating-gradients/\">repeating linear gradients</a>) for instance, are typically used for stripes. But there are other ways to create cool background patterns.&nbsp;Let&#8217;s see how we can use gradients in other ways and toss in other things, like CSS shapes and emoji, to spice things up.</p>\n\n\n\n<h3>Gradient patterns</h3>\n\n\n\n<p>There are three types of CSS gradients.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img src=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/G4UQFo_.png?fit=1024%2C328&amp;ssl=1\" alt=\"\" class=\"wp-image-312444\" srcset=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/G4UQFo_.png?w=1033&amp;ssl=1 1033w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/G4UQFo_.png?resize=300%2C96&amp;ssl=1 300w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/G4UQFo_.png?resize=1024%2C328&amp;ssl=1 1024w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/G4UQFo_.png?resize=768%2C246&amp;ssl=1 768w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/G4UQFo_.png?resize=1000%2C320&amp;ssl=1 1000w\" sizes=\"(min-width: 735px) 864px, 96vw\" /><figcaption>Linear&nbsp;(left),&nbsp;radial&nbsp;(center)&nbsp;and conic&nbsp;(right)&nbsp;gradients</figcaption></figure>\n\n\n\n<ol><li><code>linear-gradient()</code>: Colors flow from left-to-right, top-to-bottom, or at any angle you choose in a single direction.</li><li><code>radial-gradient()</code>: Colors start at a single point and emanate outward</li><li><code>conic-gradient()</code>: Similar in concept to radial gradients, but the color stops are placed around the circle rather than emanating from the center point.</li></ol>\n\n\n\n<p class=\"explanation\">I recommend <a href=\"https://css-tricks.com/guides/css-gradients/\">checking out the syntax for all the gradients</a> to thoroughly understand how to start and end a color in a gradient.</p>\n\n\n\n<h4>Radial gradient patterns</h4>\n\n\n\n<p>Let’s look at <a href=\"https://css-tricks.com/snippets/css/css-radial-gradient/\">radial gradients</a> first because they give us very useful things: <strong>circles</strong> and <strong>ellipses</strong>. Both can be used for patterns that are very interesting and might unlock some ideas for you!</p>\n\n\n\n<pre rel=\" \" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">background: radial-gradient(&lt;gradient values>)</code></pre>\n\n\n\n<p>Here&#8217;s a pattern of repeating watermelons using this technique:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_mdeKVeL\" src=\"//codepen.io/anon/embed/mdeKVeL?height=600&amp;theme-id=1&amp;slug-hash=mdeKVeL&amp;default-tab=result\" height=\"600\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed mdeKVeL\" title=\"CodePen Embed mdeKVeL\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">background: \n	radial-gradient(circle at 25px 9px, black 2px, transparent 2px), \n	radial-gradient(circle at 49px 28px, black 2px, transparent 2px), \n	radial-gradient(circle at 38px 1px, black 2px, transparent 2px), \n	radial-gradient(circle at 20px 4px, black 2px, transparent 2px), \n	radial-gradient(circle at 80px 4px, black 2px, transparent 2px), \n	radial-gradient(circle at 50px 10px, black 2px, transparent 2px), \n	radial-gradient(circle at 60px 16px, black 2px, transparent 2px), \n	radial-gradient(circle at 70px 16px, black 2px, transparent 2px), \n	radial-gradient(ellipse at 50px 0, red 33px, lime 33px, lime 38px, transparent 38px) \n	white;\nbackground-size: 100px 50px;</code></pre>\n\n\n\n<p>We start by providing a background size on the element then stack up the gradients inside it. An ellipse forms the green and red parts. Black circles are scattered across to represent the watermelon seeds.&nbsp;</p>\n\n\n\n<p>The first two parameters for a radial gradient function determine whether the gradient shape is a circle or an ellipse and the starting position of the gradient. That’s followed by the gradient color values along with the start and ending positions within the gradient.</p>\n\n\n\n<h4>Conic gradient patterns</h4>\n\n\n\n<p>Conic gradients create ray-like shapes. Like linear and radial gradients, <a href=\"https://css-tricks.com/snippets/css/css-conic-gradient/\">conic gradients</a> can be used to create geometric patterns.</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">background: conic-gradient(&lt;gradient values>)</code></pre>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_BaoGPqo\" src=\"//codepen.io/anon/embed/BaoGPqo?height=600&amp;theme-id=1&amp;slug-hash=BaoGPqo&amp;default-tab=result\" height=\"600\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed BaoGPqo\" title=\"CodePen Embed BaoGPqo\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">background: \n  conic-gradient(yellow 40deg, blue 40deg, blue 45deg, transparent 45deg), \n  conic-gradient(transparent 135deg, blue 135deg, blue 140deg, transparent 140deg) ;\nbackground-size: 60px 60px;\nbackground-color: white;</code></pre>\n\n\n\n<p>The rub with conic gradient is that it&#8217;s not supported in Firefox, at least at the time of writing. It’s always worth keeping an eye out for deeper support.</p>\n\n\n<div class=\"caniuse\"><div class=\"caniuse-header\"><p>This browser support data is from <a href=\"http://caniuse.com/#feat=”css-conic-gradients”\">Caniuse</a>, which has more detail. A number indicates that browser supports the feature at that version and up.</p></div><div class=\"caniuse-section\"><h4>Desktop</h4><table class=\"browser-support-table\"><thead><tr><th class=\"chrome\"><span>Chrome</span></th><th class=\"firefox\"><span>Firefox</span></th><th class=\"ie\"><span>IE</span></th><th class=\"edge\"><span>Edge</span></th><th class=\"safari\"><span>Safari</span></th></tr></thead><tbody><tr><td class=\"y yep\" title=\"Chrome - \"><span class=\"caniuse-agents-version version\">69</span></td><td class=\"n nope\" title=\"Firefox - \"><span class=\"caniuse-agents-version version\">No</span></td><td class=\"n nope\" title=\"IE - \"><span class=\"caniuse-agents-version version\">No</span></td><td class=\"y yep\" title=\"Edge - \"><span class=\"caniuse-agents-version version\">79</span></td><td class=\"y yep\" title=\"Safari - \"><span class=\"caniuse-agents-version version\">12.1</span></td></tr></table></div><div class=\"caniuse-section\"><h4>Mobile / Tablet</h4><table class=\"browser-support-table\"><thead><tr><th class=\"and_chr\"><span>Android Chrome</span></th><th class=\"and_ff\"><span>Android Firefox</span></th><th class=\"android\"><span>Android</span></th><th class=\"ios_saf\"><span>iOS Safari</span></th></tr></thead><tbody><tr><td class=\"y yep\" title=\"Android Chrome - \"><span class=\"caniuse-agents-version version\">81</span></td><td class=\"n nope\" title=\"Android Firefox - \"><span class=\"caniuse-agents-version version\">No</span></td><td class=\"y yep\" title=\"Android - \"><span class=\"caniuse-agents-version version\">81</span></td><td class=\"y yep\" title=\"iOS Safari - \"><span class=\"caniuse-agents-version version\">12.2-12.4</span></td></tr></table></div></div>\n\n\n\n<h3><strong>Emoji icon</strong> patterns</h3>\n\n\n\n<p>This is where things begin to get interesting. Rather than just using geometric patterns (as in gradients), we now use the organic shapes of emojis to create background patterns. &#x1f389;&nbsp;</p>\n\n\n\n<p>It starts with emoji icons.&nbsp;</p>\n\n\n\n<h4>Solid-color emoji patterns</h4>\n\n\n\n<p>We can <a href=\"https://preethisam.com/2018/06/25/how-to-use-emojis-as-icons/\">create emoji icons</a> by giving emojis a transparent color and text shadow.</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">color: transparent;\ntext-shadow: 0 0 black;</code></pre>\n\n\n\n<p>Those icons can then be turned into an image that can be used as a background, using SVG.</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">&lt;svg>\n  &lt;foreignObject>\n    &lt;!-- The HTML code with emoji -->\n  &lt;/foreignObject>\n&lt;/svg></code></pre>\n\n\n\n<p>The SVG can then be referred by the background property using <a href=\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Basics_of_HTTP/Data_URIs\">data URL</a>.&nbsp;</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">background: url(\"data:image/svg+xml,&lt;svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22>&lt;!-- SVG code -->&lt;/svg>\");</code></pre>\n\n\n\n<p>And, <em>voilá</em>! We get something like this:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_bGVQjME\" src=\"//codepen.io/anon/embed/bGVQjME?height=600&amp;theme-id=1&amp;slug-hash=bGVQjME&amp;default-tab=result\" height=\"600\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed bGVQjME\" title=\"CodePen Embed bGVQjME\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">background: \n    url(\"data:image/svg+xml,&lt;svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22>&lt;foreignObject width=%22100px%22 height=%22100px%22>&lt;div xmlns=%22http://www.w3.org/1999/xhtml%22 style=%22color:transparent;text-shadow: 0 0 %23e42100, -2px 2px 0 black;font-size:70px%22>&#x1f3c4;&#x200d;&#x2640;&#xfe0f;&lt;/div>&lt;/foreignObject>&lt;/svg>\"), \n    white; \nbackground-size: 60px 60px; </code></pre>\n\n\n\n<p class=\"explanation\">Other than emojis, it’s also possible to <a href=\"https://css-tricks.com/the-shapes-of-css/\">draw CSS shapes</a> and use them as patterns. Emojis are less work, though. Just saying.&nbsp;</p>\n\n\n\n<h4>Gradient-colored emoji patterns</h4>\n\n\n\n<p>Instead of using plain emoji icons, we can use gradient emoji icons. To do that, skip the text shadow on the emojis. Add a gradient background behind them and use <a href=\"https://css-tricks.com/almanac/properties/b/background-clip/\"><code>background-clip</code></a> to trim the gradient background to the shape of the emojis.&nbsp;</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">color: transparent;\nbackground: linear-gradient(45deg, blue 20%, fuchsia);\nbackground-clip: text; /* Safari requires -webkit prefix */</code></pre>\n\n\n\n<p>Then, just as before, use the combination of SVG and data URL to create the background pattern.</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_WNQYKKx\" src=\"//codepen.io/anon/embed/WNQYKKx?height=600&amp;theme-id=1&amp;slug-hash=WNQYKKx&amp;default-tab=result\" height=\"600\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed WNQYKKx\" title=\"CodePen Embed WNQYKKx\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<h4>Translucent-colored emoji patterns</h4>\n\n\n\n<p>This is same as using block colored emoji icons. This time, however, we take away the opaqueness of the colors by using <code>rgba()</code> or <code>hsla()</code> values for the text shadow.&nbsp;</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">color: transparent;\ntext-shadow: 20px 10px rgba(0, 255, 0, .3), \n             0 0 red;</code></pre>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_BaoGPOo\" src=\"//codepen.io/anon/embed/BaoGPOo?height=600&amp;theme-id=1&amp;slug-hash=BaoGPOo&amp;default-tab=result\" height=\"600\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed BaoGPOo\" title=\"CodePen Embed BaoGPOo\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<h4>SVG-text emoji patterns</h4>\n\n\n\n<p>We’ve already looked at all the working methods I could think of to create background patterns, but I feel like I should also mention this other technique I tried, which is not as widely supported as I’d hoped.</p>\n\n\n\n<p>&nbsp;I tried placing the emoji in an SVG &lt;text&gt; element instead of the HTML added using <code>&lt;foreignObject&gt;</code>. But I wasn’t able to create a solid shadow behind it in all the browsers.</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_JjYqqgV\" src=\"//codepen.io/anon/embed/JjYqqgV?height=600&amp;theme-id=1&amp;slug-hash=JjYqqgV&amp;default-tab=result\" height=\"600\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed JjYqqgV\" title=\"CodePen Embed JjYqqgV\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">background: \n  url(\"data:image/svg+xml,&lt;svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22>&lt;text y=%221em%22 font-size=%2270%22 fill=%22transparent%22 style=%22text-shadow: 0 0 %23e42100, -2px 2px 5px black, 0 0 6px white; ;%22>&#x1f3c4;&#x200d;&#x2640;&#xfe0f;&lt;/text>&lt;/svg>\")\n</code></pre>\n\n\n\n<p>Just in case, I tried using CSS and SVG filters for the shadow as well, thinking that might work. It didn’t. I also tried using the stroke attribute, to at least create an outline for the emoji, but that didn’t work, either.&nbsp;</p>\n\n\n\n<h3>CSS <code>element()</code> patterns</h3>\n\n\n\n<p>I didn’t think of SVG when I first thought of converting emoji icons or CSS shapes into background images. I tried CSS <a href=\"https://developer.mozilla.org/en-US/docs/Web/CSS/element\"><code>element()</code></a>. It’s a function that directly converts an HTML element into an image that can be referenced and used. I really like this approach, but browser support is a huge caveat, which is why I’m mentioning it here at the end.</p>\n\n\n\n<p>Basically, we can drop an element in the HTML like this:</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">&lt;div id=snake >&#x1f40d;&lt;/div></code></pre>\n\n\n\n<p>…then pass it into the <code>element()</code> function to use like an image on other elements, like this:</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"2\"><code markup=\"tt\">background: \n  -moz-element(#snake), /* Firefox only */\n  linear-gradient(45deg, transparent 20px, blue 20px, blue 30px, transparent 30px) \n  white;\nbackground-size: 60px 60px;\nbackground-color: white;</code></pre>\n\n\n\n<p>Now that snake emoji is technically an image that we get to include in the pattern.</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_ExVOpOR\" src=\"//codepen.io/anon/embed/ExVOpOR?height=600&amp;theme-id=1&amp;slug-hash=ExVOpOR&amp;default-tab=result\" height=\"600\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed ExVOpOR\" title=\"CodePen Embed ExVOpOR\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>Again, browser support is spotty, making this approach super experimental.</p>\n\n\n<div class=\"caniuse\"><div class=\"caniuse-header\"><p>This browser support data is from <a href=\"http://caniuse.com/#feat=”css-element-function”’\">Caniuse</a>, which has more detail. A number indicates that browser supports the feature at that version and up.</p></div><div class=\"caniuse-section\"><h4>Desktop</h4><table class=\"browser-support-table\"><thead><tr><th class=\"chrome\"><span>Chrome</span></th><th class=\"firefox\"><span>Firefox</span></th><th class=\"ie\"><span>IE</span></th><th class=\"edge\"><span>Edge</span></th><th class=\"safari\"><span>Safari</span></th></tr></thead><tbody><tr><td class=\"n nope\" title=\"Chrome - \"><span class=\"caniuse-agents-version version\">No</span></td><td class=\"y yep\" title=\"Firefox - \"><span class=\"caniuse-agents-version version\">4*</span></td><td class=\"n nope\" title=\"IE - \"><span class=\"caniuse-agents-version version\">No</span></td><td class=\"n nope\" title=\"Edge - \"><span class=\"caniuse-agents-version version\">No</span></td><td class=\"n nope\" title=\"Safari - \"><span class=\"caniuse-agents-version version\">No</span></td></tr></table></div><div class=\"caniuse-section\"><h4>Mobile / Tablet</h4><table class=\"browser-support-table\"><thead><tr><th class=\"and_chr\"><span>Android Chrome</span></th><th class=\"and_ff\"><span>Android Firefox</span></th><th class=\"android\"><span>Android</span></th><th class=\"ios_saf\"><span>iOS Safari</span></th></tr></thead><tbody><tr><td class=\"n nope\" title=\"Android Chrome - \"><span class=\"caniuse-agents-version version\">No</span></td><td class=\"y yep\" title=\"Android Firefox - \"><span class=\"caniuse-agents-version version\">68*</span></td><td class=\"n nope\" title=\"Android - \"><span class=\"caniuse-agents-version version\">No</span></td><td class=\"n nope\" title=\"iOS Safari - \"><span class=\"caniuse-agents-version version\">No</span></td></tr></table></div></div>\n\n\n\n<p>In this method, the original emoji (or any CSS shape for that matter) used for the background pattern needs to render on screen for it to appear in the background pattern as well. To hide that original emoji, I used mix-blend-mode — it sort of masks out the original emoji in the HTML so it doesn’t show up on the page.</p>\n\n\n\n<hr class=\"wp-block-separator\"/>\n\n\n\n<p>I hope you find the methods in this post useful in one way or another and learned something new in the process! Give them a try. Experiment with different emojis and CSS shapes because gradients, while cool and all, aren’t the only way to make patterns.. The <code>background</code> property takes multiple values, allowing us to think of creative ways to stack things.</p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/creative-background-patterns-using-gradients-css-shapes-and-even-emojis/\">Creative Background Patterns Using Gradients, CSS Shapes, and Even Emojis</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 'Tips, Tricks, and Techniques on using Cascading Style Sheets.', 'basic_html'),
('feed_rss', 0, 1010, 1010, 'en', 0, '\n<p>I discovered CSS about a decade ago while trying to modify the look of a blog I had created. Pretty soon, I was able to code <a href=\"https://codepen.io/thebabydino/details/GRgYQge\">cool things</a> with more mathematical and, therefore, easier-to-understand features like transforms. However, other areas of CSS, such as layout, have remained a constant source of pain.</p>\n\n\n\n<p>This post is about a problem I encountered about a decade ago and, until recently, did not know how to solve in a smart way. Specifically, it&#8217;s about how I found a solution to a long-running problem using a modern CSS grid technique that, in the process, gave me even cooler results than I originally imagined.</p>\n\n\n\n<span id=\"more-311528\"></span>\n\n\n\n<p class=\"explanation\">That this is not a tutorial on how to best use CSS grid, but more of a walk through my own learning process.</p>\n\n\n\n<h3 id=\"the-problem\">The problem</h3>\n\n\n\n<p>One of the first things I used to dump on that blog were random photos from the city, so I had this idea about having a grid of thumbnails with a fixed size. For a nicer look, I wanted this grid to be middle-aligned with respect to the paragraphs above and below it, but, at the same time, I wanted the thumbnails on the last row to be left-aligned with respect to the grid. Meanwhile, the width of the post (and the width of the grid within it) would depend on the viewport.</p>\n\n\n\n<figure><video src=\"https://videos.files.wordpress.com/f24Y9Zob/thumb_grid_prob_hd.mp4\" controls></figure>\n\n\n\n<p>The HTML looks something like this:</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">&lt;section class=\'post__content\'>\n  &lt;p>&lt;!-- some text -->&lt;/p>\n  &lt;div class=\'grid--thumbs\'>\n    &lt;a href=\'full-size-image.jpg\'>\n      &lt;img src=\'thumb-image.jpg\' alt=\'image description\'/>\n    &lt;/a>\n    &lt;!-- more such thumbnails -->\n  &lt;/div>\n  &lt;p>&lt;!-- some more text -->&lt;/p>\n&lt;/section></code></pre>\n\n\n\n<p>It may seem simple, but it turned out to be one of the most difficult CSS problems I&#8217;ve ever encountered.</p>\n\n\n\n<h3 id=\"bad-solutions\">Less than ideal solutions</h3>\n\n\n\n<p>These are things I have tried or seen suggested over the years, but that never really got me anywhere.</p>\n\n\n\n<h4 id=\"bad-float\">Floating impossibility</h4>\n\n\n\n<p>Floats turned out to be a dead end because I couldn&#8217;t figure out how to make the grid be middle aligned this way.</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">.grid--thumbs { overflow: hidden; }\n\n.grid--thumbs a { float: left; }</code></pre>\n\n\n\n<p>The demo below shows the float attempt. Resize the embed to see how they behave at different viewport widths.</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_ZEbmLMa\" src=\"//codepen.io/anon/embed/ZEbmLMa?height=500&amp;theme-id=1&amp;slug-hash=ZEbmLMa&amp;default-tab=result\" height=\"500\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed ZEbmLMa\" title=\"CodePen Embed ZEbmLMa\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<h4 id=\"bad-inline-block\"><code>inline-block</code> madness</h4>\n\n\n\n<p>At first, this seemed like a better idea:</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">.grid--thumbs { text-align: center }\n\n.grid--thumbs a { display: inline-block }</code></pre>\n\n\n\n<p>Except it turned out it wasn&#8217;t:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_JjYeWao\" src=\"//codepen.io/anon/embed/JjYeWao?height=550&amp;theme-id=1&amp;slug-hash=JjYeWao&amp;default-tab=result\" height=\"550\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed JjYeWao\" title=\"CodePen Embed JjYeWao\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>The last row isn&#8217;t left aligned in this case.</p>\n\n\n\n<p>At a certain point, thanks to an accidental CSS auto-complete on CodePen, I found out about a property called <code><a href=\"https://css-tricks.com/almanac/properties/t/text-align-last/\">text-align-last</a></code>, which determines how the last line of a block is aligned.</p>\n\n\n\n<p>Unfortunately, setting <code>text-align-last: left</code> on the grid wasn&#8217;t the solution I was looking for either:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_LYpXWoN\" src=\"//codepen.io/anon/embed/LYpXWoN?height=550&amp;theme-id=1&amp;slug-hash=LYpXWoN&amp;default-tab=result\" height=\"550\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed LYpXWoN\" title=\"CodePen Embed LYpXWoN\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>At this point, I actually considered dropping the idea of a middle aligned grid. Could a combo of <code>text-align: justified</code> and <code>text-align-last: left</code> on the grid produce a better result?</p>\n\n\n\n<p>Well, turns out it doesn&#8217;t. That is, unless there&#8217;s only a thumbnail on the last row and the gaps between the columns aren&#8217;t too big. Resize the embed below to see what I mean.</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_QWjJvWJ\" src=\"//codepen.io/anon/embed/QWjJvWJ?height=550&amp;theme-id=1&amp;slug-hash=QWjJvWJ&amp;default-tab=result\" height=\"550\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed QWjJvWJ\" title=\"CodePen Embed QWjJvWJ\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>This is pretty where I was at two years ago, after nine years of trying and failing to come up with a solution to this problem.</p>\n\n\n\n<h4 id=\"bad-flex\">Messy flexbox hacks</h4>\n\n\n\n<p>A flexbox solution that seemed like it would work at first was to add an <code>::after</code> pseudo-element on the grid and set <code>flex: 1</code> on both the thumbnails and this pseudo-element:</p>\n\n\n\n<pre rel=\"SCSS\" class=\"wp-block-csstricks-code-block language-scss\" data-line=\"\"><code markup=\"tt\">.grid--thumbs {\n  display: flex;\n  flex-wrap: wrap;\n	\n  a, &amp;::after { flex: 1; }\n	\n  img { margin: auto; }\n	\n  &amp;:after { content: \'AFTER\'; }\n}</code></pre>\n\n\n\n<p>The demo below shows how this method works. I&#8217;ve given the thumbnails and the <code>::after</code> pseudo-element purple outlines to make it easier to see what is going on.</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_GRpwmqQ\" src=\"//codepen.io/anon/embed/GRpwmqQ?height=550&amp;theme-id=1&amp;slug-hash=GRpwmqQ&amp;default-tab=result\" height=\"550\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed GRpwmqQ\" title=\"CodePen Embed GRpwmqQ\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>This is not quite what I wanted because the grid of thumbnails is not middle-aligned. Thats said, it doesn&#8217;t look too bad&#8230; as long as the last row has exactly one item less image than the others. As soon as that changes, however, the layout breaks if it&#8217;s missing more items or none.</p>\n\n\n\n<figure class=\"wp-block-image\"><img src=\"https://i2.wp.com/css-tricks.com/wp-content/uploads/2020/05/screen_flex_after_issue.png?ssl=1\" alt=\"Screenshot collage. Shows how the layout breaks when the last row is not missing exactly one item to be full.\" data-recalc-dims=\"1\"/><figcaption>Why the <code>::after</code> hack is not reliable.</figcaption></figure>\n\n\n\n<p>That was one hacky idea. Another is to use a pseudo-element again, but add as many empty divs after the thumbnails as there are columns that we&#8217;re expecting to have. That number is something we should be able to approximate since the size of the thumbnails is fixed. We probably want to set a maximum width for the post since text that stretches across the width of a full screen can visually exhausting for eyes to read.</p>\n\n\n\n<p>The first empty elements will take up the full width of the row that&#8217;s not completely filled with thumbnails, while the rest will spill into other rows. But since their <code>height</code> is zero, it won&#8217;t matter visually.</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_VwvVqxv\" src=\"//codepen.io/anon/embed/VwvVqxv?height=550&amp;theme-id=1&amp;slug-hash=VwvVqxv&amp;default-tab=result\" height=\"550\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed VwvVqxv\" title=\"CodePen Embed VwvVqxv\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>This kind of does the trick but, again, it&#8217;s hacky and still doesn&#8217;t produce the exact result I want since it sometimes ends up with big and kind of ugly-looking gaps between the columns.</p>\n\n\n\n<h4 id=\"bad-grid\">A grid solution?</h4>\n\n\n\n<p>The grid layout has always sounded like the answer, given its name. The problem was that all examples I had seen by then were using a predefined number of columns and that doesn&#8217;t work for this particular pattern where the number of columns is determined by the viewport width.</p>\n\n\n\n<p>Last year, while coding a collection of one element, pure CSS background patterns, I had the idea of generating a bunch of media queries that would modify a CSS variable, <code>--n</code>, corresponding to the number of columns used to set <code>grid-template-columns</code>.</p>\n\n\n\n<pre rel=\"SCSS\" class=\"wp-block-csstricks-code-block language-scss\" data-line=\"\"><code markup=\"tt\">$w: 13em;\n$h: 19em;\n$f: $h/$w;\n$n: 7;\n$g: 1em;\n\n--h: #{$f*$w};\ndisplay: grid;\ngrid-template-columns: repeat(var(--n, #{$n}), var(--w, #{$w}));\ngrid-gap: $g;\nplace-content: center;\n	\n@for $i from 1 to $n {\n  @media (max-width: ($n - $i + 1)*$w + ($n - $i + 2)*$g) {\n    --n: #{$n - $i}\n  }\n}</code></pre>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_GRRpzNX\" src=\"//codepen.io/anon/embed/GRRpzNX?height=600&amp;theme-id=1&amp;slug-hash=GRRpzNX&amp;default-tab=result\" height=\"600\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed GRRpzNX\" title=\"CodePen Embed GRRpzNX\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>I was actually super proud of this idea at the time, even though I cringe looking back on it now. One media query for every number of columns possible is not exactly ideal, not to mention it doesn&#8217;t work so well when the grid width doesn&#8217;t equal the viewport width, but is still somewhat flexible and also depends on the width of its siblings.</p>\n\n\n\n<h3 id=\"magic-solution\">A magic solution</h3>\n\n\n\n<p>I finally came across a better solution while working with CSS grid and failing to understand why the <code>repeat()</code> function wasn&#8217;t working in a particular situation. It was so frustrating and prompted me to go to MDN, where I happened to notice the <code><a href=\"https://css-tricks.com/auto-sizing-columns-css-grid-auto-fill-vs-auto-fit/\">auto-fit</a></code> keyword and, while I didn&#8217;t understand the explanation, I had a hunch that it could help with <em>this</em> other problem, so I dropped everything else I was doing and gave it a try.</p>\n\n\n\n<p>Here&#8217;s what I got:</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">.grid--thumbs {\n  display: grid;\n  justify-content: center;\n  grid-gap: .25em;\n  grid-template-columns: repeat(auto-fit, 8em);\n}</code></pre>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_eYpQbQx\" src=\"//codepen.io/anon/embed/eYpQbQx?height=500&amp;theme-id=1&amp;slug-hash=eYpQbQx&amp;default-tab=result\" height=\"500\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed eYpQbQx\" title=\"CodePen Embed eYpQbQx\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>I also discovered the <a href=\"https://developer.mozilla.org/en-US/docs/Web/CSS/minmax\"><code>minmax()</code></a> function, which can be used in place of fixed sizes on grid items. I still haven&#8217;t been able to understand exactly how <code>minmax()</code> works — and the more I play with it, the less I understand it — but what it looks like it does in this situation is create the grid then stretch its columns equally until they fill all of the available space:</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">grid-template-columns: repeat(auto-fit, minmax(8em, 1fr));</code></pre>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_eYpbQgd\" src=\"//codepen.io/anon/embed/eYpbQgd?height=550&amp;theme-id=1&amp;slug-hash=eYpbQgd&amp;default-tab=result\" height=\"550\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed eYpbQgd\" title=\"CodePen Embed eYpbQgd\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>Another cool thing we can do here is prevent the image from overflowing when it&#8217;s wider than the grid element. We can do this by replacing the minimum <code>8em</code> with <code>min(8em, 100%)</code> That essentially ensures that images will never exceed 100%, but never below 8em. Thanks to Chris for this suggestion!</p>\n\n\n\n<p class=\"explanation\">Note that the <a href=\"https://developer.mozilla.org/en-US/docs/Web/CSS/min\"><code>min()</code></a> function doesn&#8217;t work in pre-Chromium Edge!</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_ZEbVVpv\" src=\"//codepen.io/anon/embed/ZEbVVpv?height=550&amp;theme-id=1&amp;slug-hash=ZEbVVpv&amp;default-tab=result\" height=\"550\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed ZEbVVpv\" title=\"CodePen Embed ZEbVVpv\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>Keep in mind that this only produces a nice result if all of the images have the same aspect ratio — like the square images I&#8217;ve used here. For my blog, this was not an issue since all photos were taken with my Sony Ericsson W800i phone, and they all had the same aspect ratio. But if we were to drop images with different aspect ratios, the grid wouldn&#8217;t look as good anymore:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_dyYwazO\" src=\"//codepen.io/anon/embed/dyYwazO?height=650&amp;theme-id=1&amp;slug-hash=dyYwazO&amp;default-tab=result\" height=\"650\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed dyYwazO\" title=\"CodePen Embed dyYwazO\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>We can, of course, set the image <code>height</code> to a fixed value, but that distorts the images&#8230; unless we set <a href=\"https://css-tricks.com/on-object-fit-and-object-position/\"><code>object-fit</code></a> to <code>cover</code>, which solves our problem!</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_JjYwzmL\" src=\"//codepen.io/anon/embed/JjYwzmL?height=450&amp;theme-id=1&amp;slug-hash=JjYwzmL&amp;default-tab=result\" height=\"450\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed JjYwzmL\" title=\"CodePen Embed JjYwzmL\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>Another idea would be to turn the first thumbnail into a sort of banner that spans all grid columns. The one problem is that we don&#8217;t know the number of columns because that depends on the viewport. But, there <em>is</em> a solution — we can set <code>grid-column-end</code> to <code>-1</code>!</p>\n\n\n\n<pre rel=\"SCSS\" class=\"wp-block-csstricks-code-block language-scss\" data-line=\"\"><code markup=\"tt\">.grid--thumbs {\n  /* same styles as before */\n	\n  a:first-child {\n    grid-column: 1/ -1;\n		\n    img { height: 13em }\n  }\n}</code></pre>\n\n\n\n<p>The first image gets a bigger <code>height</code> than all the others.</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_vYNbJJo\" src=\"//codepen.io/anon/embed/vYNbJJo?height=650&amp;theme-id=1&amp;slug-hash=vYNbJJo&amp;default-tab=result\" height=\"650\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed vYNbJJo\" title=\"CodePen Embed vYNbJJo\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>Of course, if we wanted the image to span all columns except the last, one we&#8217;d set it to <code>-2</code> and so on&#8230; negative column indices are a thing!</p>\n\n\n\n<p><code>auto-fill</code> is another grid property keyword I noticed on MDN. The explanations for both are long walls of text without visuals, so I didn&#8217;t find them particularly useful. Even worse, replacing <code>auto-fit</code> with <code>auto-fill</code> in any of the grid demos above produces absolutely no difference. How they really work and how they differ still remains a mystery, even after checking out <a href=\"https://css-tricks.com/auto-sizing-columns-css-grid-auto-fill-vs-auto-fit/#article-header-id-0\">articles</a> or toying with <a href=\"https://gridbyexample.com/examples/example37/\">examples</a>.</p>\n\n\n\n<p>However, trying out different things and seeing what happens in various scenarios at one point led me to the conclusion that, if we&#8217;re using a <code>minmax()</code> column width and not a fixed one (like <code>8em</code>), then it&#8217;s probably better to use <code>auto-fill</code> instead of <code>auto-fit</code> because, the result looks better if we happen to only have a few images, as illustrated by the interactive demo below:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_QWjovRV\" src=\"//codepen.io/anon/embed/QWjovRV?height=650&amp;theme-id=1&amp;slug-hash=QWjovRV&amp;default-tab=result\" height=\"650\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed QWjovRV\" title=\"CodePen Embed QWjovRV\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>I think what I personally like best is the initial idea of a thumbnail grid that&#8217;s middle-aligned and has a mostly fixed column width (but still uses <code>min(100%, 15em)</code> instead of just <code>15em</code> though). At the end of the day, it&#8217;s a matter of personal preference and what can be seen in the demo below just happens to look better to me:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_yLYPzgd\" src=\"//codepen.io/anon/embed/yLYPzgd?height=650&amp;theme-id=1&amp;slug-hash=yLYPzgd&amp;default-tab=result\" height=\"650\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed yLYPzgd\" title=\"CodePen Embed yLYPzgd\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>I&#8217;m using <code>auto-fit</code> in this demo because it produces the same result as <code>auto-fill</code> and is one character shorter. However, what I didn&#8217;t understand when making this is that both keywords produce the same result because there are more items in the gallery than we need to fill a row.</p>\n\n\n\n<p>But once that changes, <code>auto-fit</code> and <code>auto-fill</code> produce different results, as illustrated below. You can change the <code>justify-content</code> value and the number of items placed on the grid:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_gOayvpb\" src=\"//codepen.io/anon/embed/gOayvpb?height=750&amp;theme-id=1&amp;slug-hash=gOayvpb&amp;default-tab=result\" height=\"750\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed gOayvpb\" title=\"CodePen Embed gOayvpb\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>I&#8217;m not really sure which is the better choice. I guess this also depends on personal preference. Coupled with <code>justify-content: center</code>, <code>auto-fill</code> seems to be the more logical option, but, at the same time, <code>auto-fit</code> produces a better-looking result.</p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/cool-little-css-grid-tricks-for-your-blog/\">Cool Little CSS Grid Tricks for Your Blog</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 'Tips, Tricks, and Techniques on using Cascading Style Sheets.', 'basic_html');
INSERT INTO `node__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('feed_rss', 0, 1012, 1012, 'en', 0, '\n<p>Jamstack isn&#8217;t necessarily new. The term was officially coined in 2016, but the technologies and architecture it describes have been around well before that. Jamstack has received a massive dose of attention recently, with articles about it appearing in major sites and publications and new Jamstack-focused <a href=\"https://jamstackconf.com/\">events</a>, <a href=\"https://jamstack.email/\">newsletters</a>, <a href=\"https://thatsmyjamstack.com/\">podcasts</a>, and more. As someone who follows it closely, I&#8217;ve even seen what seems like a significant uptick in discussion about it on Twitter, often from people who are being newly introduced to the concept.</p>\n\n\n\n<p>The buzz has also seemed to bring out the criticism. Some of the criticism is fair, and I&#8217;ll get to some of that in a bit, but others appear to be based on common myths about the Jamstack that persist, which is what I want to address first. So let&#8217;s look at five common myths about Jamstack I&#8217;ve encountered and debunk them. As with many myths, they are often based on a kernel of truth but lead to invalid conclusions.</p>\n\n\n\n<span id=\"more-310812\"></span>\n\n\n\n<h2>Myth 1: They are just rebranded static sites</h2>\n\n\n\n<figure class=\"wp-block-embed-twitter wp-block-embed is-type-rich is-provider-twitter\"><div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"twitter-tweet\" data-width=\"500\" data-dnt=\"true\"><p lang=\"en\" dir=\"ltr\">JAMStack is 99.9% branding and .1% substance. 😳😆 <a href=\"https://t.co/nxoEVQ43oE\">https://t.co/nxoEVQ43oE</a></p>&mdash; Nicole Sullivan &#8211; Black Lives Matter (@stubbornella) <a href=\"https://twitter.com/stubbornella/status/1226365361722773508?ref_src=twsrc%5Etfw\">February 9, 2020</a></blockquote><script async src=\"https://platform.twitter.com/widgets.js\" charset=\"utf-8\"></script>\n</div></figure>\n\n\n\n<p>Yes, <a href=\"https://remotesynthesis.com/blog/jamstack-is-just-branding\">as I covered previously</a>, the term &#8220;Jamstack&#8221; was arguably a rebranding of what we previously called &#8220;static sites.&#8221; This was not a rebranding meant to mislead or sell you something that wasn&#8217;t fully formed — quite the opposite. The term &#8220;static site&#8221; had long since lost its ability to describe what people were building. The sites being built using static site generators (SSG) were frequently filled with all sorts of dynamic content and capabilities.</p>\n\n\n\n<p>Static sites were seen as largely about blogs and documentation where the UI was primarily fixed. The extent of interaction was perhaps embedded comments and a contact form. Jamstack sites, on the other hand, have things like user authentication, dynamic content, ecommerce, user generated content.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img src=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/05/image.png?ssl=1\" alt=\"\" class=\"wp-image-310815\" srcset=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/05/image.png?w=750&amp;ssl=1 750w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/05/image.png?resize=300%2C205&amp;ssl=1 300w\" sizes=\"(min-width: 735px) 864px, 96vw\" data-recalc-dims=\"1\" /><figcaption>A listing of <a href=\"https://jamstack.org/examples/\">sites built using Jamstack</a> on <a href=\"http://jamstack.org/\">Jamstack.org</a></figcaption></figure>\n\n\n\n<p>Want proof? Some well-known companies and sites built using the Jamstack include <a href=\"https://www.smashingmagazine.com/\">Smashing Magazine</a>, <a href=\"https://sphero.com/\">Sphero</a>, <a href=\"https://www.postman.com/\">Postman</a>, <a href=\"https://www.prima.co/\">Prima</a>, <a href=\"https://impossiblefoods.com/\">Impossible Foods</a> and <a href=\"https://www.trinet.com/\">TriNet</a>, just to name a few.</p>\n\n\n\n<h2>Myth 2: Jamstack sites are fragile</h2>\n\n\n\n<p>Jay Freestone, on <a href=\"https://www.browserlondon.com/blog/2020/04/20/issues-with-jamstack-you-might-need-backend/\">The issues with JAMStack: You might need a backend</a></p>\n\n\n\n<blockquote class=\"wp-block-quote\"><p>Reading the dependency list for Smashing Magazine reads like the service equivalent of&nbsp;<code>node_modules</code>, including&nbsp;<a rel=\"noreferrer noopener\" href=\"https://www.algolia.com/\" target=\"_blank\">Algolia</a>,&nbsp;<a rel=\"noreferrer noopener\" href=\"https://github.com/netlify/gocommerce\" target=\"_blank\">GoCommerce</a>,&nbsp;<a rel=\"noreferrer noopener\" href=\"https://github.com/netlify/gotrue\" target=\"_blank\">GoTrue</a>,&nbsp;<a rel=\"noreferrer noopener\" href=\"https://github.com/netlify/gotell\" target=\"_blank\">GoTell</a>&nbsp;and a variety of Netlify services to name a few. There is a huge amount of value in&nbsp;<a rel=\"noreferrer noopener\" href=\"https://www.browserlondon.com/blog/2019/12/02/digital-product-development-build-or-buy-services/\" target=\"_blank\">knowing what to outsource (and when)</a>, but it is amusing to note the complexity that has been introduced in an apparent attempt to &#8216;get back to basics&#8217;. This is to say nothing of the potential fragility in relying on so many disparate third-party services.</p></blockquote>\n\n\n\n<p>Yes, to achieve the dynamic capabilities that differentiate the Jamstack from static sites, Jamstack projects generally rely on a variety of services, both first- or third-party. Some have argued that this makes Jamstack sites particularly vulnerable for two reasons. The first, they say, is that if any one piece fails, the whole site functionality collapses. The second is that your infrastructure becomes too dependent on tools and services that you do not own.</p>\n\n\n\n<p>Let&#8217;s tackle that first argument. The majority of a Jamstack site should be pre-rendered. This means that when a user visits the site, the page and most of its content is delivered as static assets from the CDN. This is what gives Jamstack much of its speed and security. Dynamic functionality — like shopping carts, authentication, user generated content and perhaps search — rely upon a combination of serverless functions and APIs to work.</p>\n\n\n\n<p>Broadly speaking, the app will call a serverless function that serves as the back end to connect to the APIs. If, for example, our e-commerce functionality relies on Stripe&#8217;s APIs to work and Stripe is down, then, yes, our e-commerce functionality will not work. However, it&#8217;s important to note that the site won&#8217;t go down. It can handle the issue gracefully by informing the user of the issue. A server-rendered page that relies on the Stripe API for e-commerce would face the identical issue. Assuming the server-rendered page still calls the back end code for payment asynchronously, it would be no more or less fragile than the Jamstack version. On the other hand, if the server-rendering is actually dependent upon the API call, the user may be stuck waiting on a response or receive an error (a situation anyone who uses the web is very familiar with).</p>\n\n\n\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"https://i2.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-1.png?resize=360%2C340&#038;ssl=1\" alt=\"\" class=\"wp-image-310816\" width=\"360\" height=\"340\" srcset=\"https://i2.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-1.png?w=750&amp;ssl=1 750w, https://i2.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-1.png?resize=300%2C284&amp;ssl=1 300w\" sizes=\"(min-width: 735px) 864px, 96vw\" data-recalc-dims=\"1\" /></figure>\n\n\n\n<p>As for the second argument, it&#8217;s really hard to gauge the degree of dependence on third-parties for a Jamstack web app versus a server-rendered app. Many of today&#8217;s server-rendered applications still rely on APIs for a significant amount of functionality because it allows for faster development, takes advantage of the specific area of expertise of the provider, can offload responsibility for legal and other compliance issues, and more. In these cases, once again, the server-rendered version would be no more or less dependent than the Jamstack version. Admittedly, if your app relies mostly on internal or homegrown solutions, then this may be different.</p>\n\n\n\n<h2>Myth 3: Editing content is difficult</h2>\n\n\n\n<p>Kev Quirk, on <a href=\"https://kevq.uk/why-i-dont-use-a-static-site-generator/\">Why I Don’t Use A Static Site Generator</a>:</p>\n\n\n\n<blockquote class=\"wp-block-quote\"><p>Having to SSH into a Linux box, then editing a post on Vim just seems like a ridiculously high barrier for entry when it comes to writing on the go. The world is mobile first these days, like it or not, so writing on the go should be easy.</p></blockquote>\n\n\n\n<p>This issue feels like a relic of static sites past. To be clear, you do not need to SSH into a Linux box to edit your site content. There are a <a href=\"https://bejamas.io/blog/headless-cms/\">wide range of headless CMS options</a>, from completely free and open source to commercial offerings that power content for large enterprises. They offer an array of editing capabilities that rival any traditional CMS (something I&#8217;ve <a href=\"https://css-tricks.com/jamstack-cmss-have-finally-grown-up/\">talked about before</a>). The point is, there is no reason to be manually editing Markdown, YAML or JSON files, even on your blog side project. Aren&#8217;t sure how to hook all these pieces up? We&#8217;ve <a href=\"https://app.stackbit.com/create\">got a solution for that</a> too!</p>\n\n\n\n<p>One legitimate criticism has been that the headless CMS and build process can cause a disconnect between the content being edited and the change on the site. It can be difficult to preview exactly what the impact of a change is on the live site until it is published or without some complex build previewing process. This is something that is being addressed by the ecosystem. Companies like <a href=\"https://www.stackbit.com/\">Stackbit</a> (who I work for) are building tools that make this process seamless.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img src=\"https://i0.wp.com/css-tricks.com/wp-content/uploads/2020/05/live-edits.gif?ssl=1\" alt=\"Animated screenshot. A content editor is shown on a webpage with a realtime preview of changes.\" class=\"wp-image-310817\" data-recalc-dims=\"1\"/><figcaption>Editing a site using Stackbit</figcaption></figure>\n\n\n\n<p>We&#8217;re not the only ones working on solving this problem. Other solutions include <a href=\"https://tinacms.org/\">TinaCMS</a> and <a href=\"https://www.gatsbyjs.com/preview/\">Gatsby Preview</a>. I think we are close to it becoming commonplace to have the simplicity of WYSIWYG editing on a tool like Wix running on top of the Jamstack.</p>\n\n\n\n<h2>Myth 4: SEO is Hard on the Jamstack</h2>\n\n\n\n<p>Kym Ellis, on <a href=\"https://kymellis.co/jamstack-marketing-headless-cms/\">What the JAMstack means for marketing</a>:</p>\n\n\n\n<blockquote class=\"wp-block-quote\"><p>Ditching the concept of the plugin and opting for a JAMstack site which is &#8220;just HTML&#8221; doesn&#8217;t actually mean you have to give up functionality, or suddenly need to know how to code like a front-end developer to manage a site and its content.</p></blockquote>\n\n\n\n<p>I haven&#8217;t seen this one pop up as often in recent years and I think it is mostly legacy criticism of the static site days, where managing SEO-related metadata involved manually editing YAML-based frontmatter. The concern was that doing SEO properly became cumbersome and hard to maintain, particularly if you wanted to inject different metadata for each unique page that was generated or to create structured data like <a href=\"https://json-ld.org/\">JSON-LD</a>, which can be critical for enhancing your search listing.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img src=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-2.png?fit=1024%2C686&amp;ssl=1\" alt=\"\" class=\"wp-image-310818\" srcset=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-2.png?w=1184&amp;ssl=1 1184w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-2.png?resize=300%2C201&amp;ssl=1 300w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-2.png?resize=1024%2C686&amp;ssl=1 1024w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-2.png?resize=768%2C514&amp;ssl=1 768w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-2.png?resize=1000%2C670&amp;ssl=1 1000w\" sizes=\"(min-width: 735px) 864px, 96vw\" /></figure>\n\n\n\n<p>The advances in content management for the Jamstack have generally addressed the complexity of maintaining SEO metadata. In addition, because pages are pre-rendered, adding sitemaps and JSON-LD is relatively simple, provided the metadata required exists. While pre-rendering makes it easy to create the resources search engines (read: Google) need to index a site, they also, combined with CDNs, making it easier to achieve the performance benchmarks necessary to improve a site&#8217;s ranking.</p>\n\n\n\n<p>Basically, Jamstack excels at &#8220;<a href=\"https://yoast.com/what-is-technical-seo/\">technical SEO</a>&#8221; while also providing the tools necessary for content editors to supply the keyword and other metadata they require. For a more comprehensive look at Jamstack and SEO, I highly recommend checking out the <a href=\"https://bejamas.io/blog/jamstack-seo-guide/\">Jamstack SEO Guide</a> from Bejamas.</p>\n\n\n\n<h2>Myth 5: Jamstack requires heavy JavaScript frameworks</h2>\n\n\n\n<blockquote class=\"wp-block-quote\"><p>If you&#8217;re trying to sell plain ol&#8217; websites to management who are obsessed with flavour-of-the-month frameworks, a slick website promoting the benefits of &#8220;JAMstack&#8221; is a really useful thing.</p><cite>&#8211; jdietrich, <a href=\"https://news.ycombinator.com/item?id=19107374\">Hacker News</a><br></cite></blockquote>\n\n\n\n<p>Lately, it feels as if Jamstack has become synonymous with front-end JavaScript frameworks. It&#8217;s true that a lot of the most well-known solutions do depend on a front-end framework, including Gatsby (React), Next.js (React), Nuxt (Vue), VuePress (Vue), Gridsome (Vue) and Scully (Angular). This seems to be compounded by confusion around the &#8220;J&#8221; in Jamstack. While it stands for JavaScript, this does not mean that Jamstack solutions are all JavaScript-based, nor do they all require npm or JavaScript frameworks.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img src=\"https://i2.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-3.png?ssl=1\" alt=\"\" class=\"wp-image-310819\" srcset=\"https://i2.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-3.png?w=750&amp;ssl=1 750w, https://i2.wp.com/css-tricks.com/wp-content/uploads/2020/05/image-3.png?resize=300%2C200&amp;ssl=1 300w\" sizes=\"(min-width: 735px) 864px, 96vw\" data-recalc-dims=\"1\" /></figure>\n\n\n\n<p>In fact, many of the most widely used tools are not built in JavaScript, notably Hugo (Go), Jekyll (Ruby), Pelican (Python) and the recently released Bridgetown (Ruby). Meanwhile, tools like Eleventy are built using JavaScript but do not depend on a JavaScript framework. None of these tools prevent the use of a JavaScript framework, but they do not require it.</p>\n\n\n\n<p>The point here isn&#8217;t to dump on JavaScript frameworks or the tools that use them. These are great tools, used successfully by many developers. JavaScript frameworks can be very powerful tools capable of simplifying some very complex tasks. The point here is simply that the idea that a JavaScript framework is required to use the Jamstack is false — Jamstack comes in <a href=\"https://staticsitegenerators.net/\">460 flavors</a>!</p>\n\n\n\n<h2>Where we can improve</h2>\n\n\n\n<p>So that&#8217;s it, right? Jamstack is an ideal world of web development where everything isn&#8217;t just perfect, but perfectly easy. Unfortunately, no. There are plenty of legitimate criticisms of Jamstack.</p>\n\n\n\n<h3>Simplicity</h3>\n\n\n\n<p>Sebastian De Deyne, with <a href=\"https://sebastiandedeyne.com/thoughts-after-messing-around-with-the-jamstack/\">Thoughts (and doubts) after messing around with the JAMstack</a>:</p>\n\n\n\n<blockquote class=\"wp-block-quote\"><p>In my experience, the JAMstack (JavaScript, APIs, and Markup) is great until is isn&#8217;t. When the day comes that I need to add something dynamic–and that day always comes–I start scratching my head.</p></blockquote>\n\n\n\n<p>Let&#8217;s be honest: Getting started with the Jamstack isn&#8217;t easy. Sure, diving into building a blog or a simple site using a static site generator may not be terribly difficult. But try building a real site with anything dynamic and things start to get complicated fast.</p>\n\n\n\n<p>You are generally presented with a myriad of options for completing the task, making it tough to weigh the pros and cons. One of the best things about Jamstack is that it is not prescriptive, but that can make it seem unapproachable, leaving people with the impression that perhaps it isn&#8217;t suited for complex tasks.</p>\n\n\n\n<h3>Tying services together</h3>\n\n\n\n<figure class=\"wp-block-embed-twitter wp-block-embed is-type-rich is-provider-twitter\"><div class=\"wp-block-embed__wrapper\">\n<blockquote class=\"twitter-tweet\" data-width=\"500\" data-dnt=\"true\"><p lang=\"en\" dir=\"ltr\">Agreed. In yesterday&#39;s web you could grab an instrument and begin playing. Today&#39;s web development feels like a conductor trying to pull together a massive orchestra into a cohesive song &#8211; you have to understand each individual musician&#39;s part to have any chance of success.</p>&mdash; Brian Rinaldi (@remotesynth) <a href=\"https://twitter.com/remotesynth/status/1256251466597240834?ref_src=twsrc%5Etfw\">May 1, 2020</a></blockquote><script async src=\"https://platform.twitter.com/widgets.js\" charset=\"utf-8\"></script>\n</div></figure>\n\n\n\n<p>When you actually get to the point of building those dynamic features, your site can wind up being dependent on an array of services and APIs. You may be calling a headless CMS for content, a serverless function that calls an API for payment transactions, a service like Algolia for search, and so on. Bringing all those pieces together can be a very complex task. Add to that the fact that each often comes with its own dashboard and API/SDK updates, things get even more complex.</p>\n\n\n\n<p>This is why I think services like <a href=\"https://www.stackbit.com/\">Stackbit</a> and tools like <a href=\"https://redwoodjs.com/\">RedwoodJS</a> are important, as they bring together disparate pieces of the infrastructure behind a Jamstack site and make those easier to build and manage.</p>\n\n\n\n<h3>Overusing frameworks</h3>\n\n\n\n<p>In my opinion, our dependence on JavaScript frameworks for modern front-end development has been getting a much needed skeptical look lately. There are tradeoffs, as <a href=\"https://timkadlec.com/remembers/2020-04-21-the-cost-of-javascript-frameworks/\">this post by Tim Kadlec</a> recently laid out. As I said earlier, you don&#8217;t need a JavaScript framework to work in the Jamstack.</p>\n\n\n\n<p>However, the impression was created both because so many Jamstack tools rely on JavaScript frameworks and also because much of the way we teach Jamstack has been centered on using frameworks. I understand the reasoning for this — many Jamstack developers are comfortable in JavaScript frameworks and there&#8217;s no way to teach every tool, so you pick the one you like. Still, I personally believe the success of Jamstack in the long run depends on its flexibility, which (despite what I said about the simplicity above) means we need to present the diversity of solutions it offers — both with and without JavaScript frameworks.</p>\n\n\n\n<h2>Where to go from here</h2>\n\n\n\n<p>Sheesh, you made it! I know I had a lot to say, perhaps more than I even realized when I started writing, so I won&#8217;t bore you with a long conclusion other than to say that, obviously, I have presented these myths from the perspective of someone who believes very deeply in the value of the Jamstack, despite it&#8217;s flaws!</p>\n\n\n\n<p>If you are looking for a good post about when to and when not to choose Jamstack over server-side rendering, check out Chris Coyier&#8217;s recent post <a href=\"https://css-tricks.com/static-or-not/\">Static or Not?</a>.</p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/5-myths-about-jamstack/\">5 Myths About Jamstack</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 'Tips, Tricks, and Techniques on using Cascading Style Sheets.', 'basic_html'),
('feed_rss', 0, 1018, 1018, 'en', 0, '\n<p>Whenever I suspect that there&#8217;s a timing conflict causing a problem with rendering and directives, I usually opt for a JavaScript <code>setTimeout</code> with a delay.  The <code>setTimeout</code> code never makes it to production, but it does help me to understand if my code is the problem or if there&#8217;s a timing conflict.</p>\n\n\n\n<p>In working with Kotlin on Android, I&#8217;ve needed to employ the same technique.  Kotlin obviously doesn&#8217;t have a <code>setTimeout</code>, but it does have coroutines to achieve approximately the same effect.</p>\n\n\n\n<p>To run an async coroutine with delay, you can use the following Kotlin code:</p>\n\n\n\n<pre class=\"js\">\n// Create an async coroutine\nGlobalScope.launch {\n    delay(1000)\n    \n    // Execute code to test functionality\n}\n</pre>\n\n\n\n<p>The coroutine becomes async and the delay can be whatever amount of milliseconds you&#8217;d like!</p>\n<p>The post <a rel=\"nofollow\" href=\"https://davidwalsh.name/kotlin-coroutines\">Kotlin Coroutines and Delay</a> appeared first on <a rel=\"nofollow\" href=\"https://davidwalsh.name\">David Walsh Blog</a>.</p>\n<p><a href=\"https://tkjs.us/dwb\"><img style=\"margin:0 auto\" alt=\"\" src=\"https://davidwalsh.name/demo/tjs_block-1.svg\"></a></p>\n<img src=\"http://feeds.feedburner.com/~r/Bludice/~4/AtYn74mMHEo\" height=\"1\" width=\"1\" alt=\"\"/>', 'A blog featuring tutorials about JavaScript, HTML5, AJAX, PHP, CSS, WordPress, and everything else development.', 'basic_html'),
('feed_rss', 0, 1020, 1020, 'en', 0, '\n<p><a href=\"https://piccalil.li/blog/cube-css/\">A CSS methodology</a> from Andy Bell:</p>\n\n\n\n<blockquote class=\"wp-block-quote\"><p>The most important part of this methodology is the language itself: CSS. It’s key to note its existence in the name because some alternative approaches, such as <a href=\"https://css-tricks.com/bem-101/\">BEM</a>—which I have enjoyed for many years—can veer very far away from Cascading Style Sheets. I <em>love</em> CSS, though and think that its core capabilities are actually <strong>key</strong> to scalable CSS.</p></blockquote>\n\n\n\n<p>A favorite bit&#8230;</p>\n\n\n\n<blockquote class=\"wp-block-quote\"><p>[&#8230;] a design system doesn’t just make you think at a <strong>micro-level</strong>, but also at a <strong>macro-level</strong>, because you have to make not just decisions about pixels, but also high-level organisation decisions which the design system helps to solve. Design system work is actually <strong>diplomacy work</strong>, a lot of the time.</p><p>This is often where I see narrow, component-only tunnel vision fall short and really, these approaches are less design systems, but more <strong>component libraries</strong> that solve a much narrower cohort of problems.</p></blockquote>\n\n\n\n<p>I like the idea of approaching CSS both from an inside-out philosophy — focusing on styling very small specific things then grouping them together to grow bigger thing — <em>and</em> from an outside-in philosophy — not forgetting that components need to be composed together sensibly.</p>\n<p><a href=\"https://piccalil.li/blog/cube-css/\" title=\"Direct link to featured article\">Direct Link to Article</a> &#8212; <a href=\"https://css-tricks.com/cube-css/\">Permalink</a></p><p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/cube-css/\">CUBE CSS</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 'Tips, Tricks, and Techniques on using Cascading Style Sheets.', 'basic_html'),
('feed_rss', 0, 1021, 1021, 'en', 0, '\n<p>Here&#8217;s a two-second review. If an element has an ID, you can link to it with natural browser behavior. It&#8217;s great if headings have them, because it&#8217;s often useful to link directly to a specific section of content.</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">&lt;h3 id=\"step-2\">Step 2&lt;/a></code></pre>\n\n\n\n<p>Should I be so inclined, I could link right to this heading, be it from an URL, like <code>https://my-website.com/#step-2</code>, or an on-page link, like:</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">&lt;a href=\"#step-2\">Jump to Step 2&lt;/a></code></pre>\n\n\n\n<p>So, it&#8217;s ideal if all headers have unique IDs. </p>\n\n\n\n<span id=\"more-312635\"></span>\n\n\n\n<p>I find it entirely too much work to manually add IDs to all my headers though. For years and years, I did it like this using jQuery on this very site (sue me):</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">// Adjust this for targetting the headers important to have IDs\nconst $headers = $(\".article-content > h3\");\n\n$headers.each((i, el) => {\n  const $el = $(el);\n\n  // Probably a flexbox layout style page\n  if ($el.has(\"a\").length != 0) {\n    return;\n  }\n\n  let idToLink = \"\";\n\n  if ($el.attr(\"id\") === undefined) {\n    // give it ID\n    idToLink = \"article-header-id-\" + i;\n    $el.attr(\"id\", idToLink);\n  } else {\n    // already has ID\n    idToLink = $el.attr(\"id\");\n  }\n\n  const $headerLink = $(\"&lt;a />\", {\n    html: \"#\",\n    class: \"article-headline-link\",\n    href: \"#\" + idToLink\n  });\n\n  $el.addClass(\"has-header-link\").prepend($headerLink);\n});</code></pre>\n\n\n\n<p>That script goes one step further than just adding IDs (if it doesn&#8217;t already have one) by adding a <code>#</code> link right inside the heading that links to that heading. The point of that is to demonstrate that the headers <em>have</em> IDs, and makes it easy to do stuff like right-click copy-link. <a href=\"https://codepen.io/chriscoyier/pen/MWKybrQ\">Here&#8217;s that demo</a>, if you care to see it.</p>\n\n\n\n<p><strong>Problem!</strong> All the sudden this stopped working. </p>\n\n\n\n<p>Not the script itself, that works fine. But the native browser behavior that allows the browser to jump down to the heading when the page loads is what&#8217;s busted. I imagine it&#8217;s a race condition: </p>\n\n\n\n<ol><li>The HTML arrives</li><li>The page starts to render</li><li>The browser is looking for the ID in the URL to scroll down to</li><li>It doesn&#8217;t find it&#8230;</li><li><em>Oh wait there it is!</em></li><li>Scroll there. </li></ol>\n\n\n\n<p>The <em>Oh wait there it is!</em> step is from the script executing and putting that ID on the heading. I really don&#8217;t blame browsers for not jumping to dynamically-inserted links. I&#8217;m surprised this worked for as long as it did. </p>\n\n\n\n<p>It&#8217;s much better to have the IDs on the headings by the time the HTML arrives. This site is WordPress, so I knew I could do it with some kind of content filter. Turns out I didn&#8217;t even have to bother because, of course, there is a plugin for that: <a href=\"https://kybernaut.cz/\">Karolína Vyskočilová</a>&#8216;s <a href=\"https://wordpress.org/plugins/add-anchor-links/\">Add Anchor Links</a>. Works great for me. It&#8217;s technique is that it adds the ID on the anchor link itself, which is also totally fine. I guess that&#8217;s another way of avoiding messing with existing IDs. </p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img src=\"https://i0.wp.com/css-tricks.com/wp-content/uploads/2020/06/Screen-Shot-2020-06-11-at-10.50.01-AM.png?fit=1016%2C1024&amp;ssl=1\" alt=\"\" class=\"wp-image-312721\" srcset=\"https://i0.wp.com/css-tricks.com/wp-content/uploads/2020/06/Screen-Shot-2020-06-11-at-10.50.01-AM.png?w=1848&amp;ssl=1 1848w, https://i0.wp.com/css-tricks.com/wp-content/uploads/2020/06/Screen-Shot-2020-06-11-at-10.50.01-AM.png?resize=298%2C300&amp;ssl=1 298w, https://i0.wp.com/css-tricks.com/wp-content/uploads/2020/06/Screen-Shot-2020-06-11-at-10.50.01-AM.png?resize=1016%2C1024&amp;ssl=1 1016w, https://i0.wp.com/css-tricks.com/wp-content/uploads/2020/06/Screen-Shot-2020-06-11-at-10.50.01-AM.png?resize=150%2C150&amp;ssl=1 150w, https://i0.wp.com/css-tricks.com/wp-content/uploads/2020/06/Screen-Shot-2020-06-11-at-10.50.01-AM.png?resize=768%2C774&amp;ssl=1 768w, https://i0.wp.com/css-tricks.com/wp-content/uploads/2020/06/Screen-Shot-2020-06-11-at-10.50.01-AM.png?resize=1524%2C1536&amp;ssl=1 1524w, https://i0.wp.com/css-tricks.com/wp-content/uploads/2020/06/Screen-Shot-2020-06-11-at-10.50.01-AM.png?resize=1000%2C1008&amp;ssl=1 1000w, https://i0.wp.com/css-tricks.com/wp-content/uploads/2020/06/Screen-Shot-2020-06-11-at-10.50.01-AM.png?resize=100%2C100&amp;ssl=1 100w\" sizes=\"(min-width: 735px) 864px, 96vw\" /></figure>\n\n\n\n<p>If I didn&#8217;t have WordPress, I would have found some other way to process the HTML server-side to make sure there is some kind of heading link happening somehow. There is always a way. In fact, if it was too weird or cumbersome or whatever to do during the build process or in a server-side filter, I would look at doing it in a service worker. I&#8217;ve been having fun playing with <a href=\"https://blog.cloudflare.com/introducing-htmlrewriter/\">Cloudflare&#8217;s HTMLRewriter</a>, which is totally capable of this.</p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/on-adding-ids-to-headers/\">On Adding IDs to Headers</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 'Tips, Tricks, and Techniques on using Cascading Style Sheets.', 'basic_html'),
('feed_rss', 0, 1022, 1022, 'en', 0, '\n<p>I needed a numbered list of blog posts to be listed with the last/high first and going down from there. Like this:</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">5. Post Title\n4. Post Title\n3. Post Title\n2. Post Title\n1. Post Title</code></pre>\n\n\n\n<p>But the above is just text. I wanted to do this with a semantic <code>&lt;ol&gt;</code> element.</p>\n\n\n\n<span id=\"more-312104\"></span>\n\n\n\n<h3>The easy way</h3>\n\n\n\n<p>This can be done using HTML&#8217; s <code>reversed</code> property on the <code>&lt;ol&gt;</code>:</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"1\"><code markup=\"tt\">&lt;ol reversed>\n  &lt;li>This&lt;/li>\n  &lt;li>List&lt;/li>\n  &lt;li>Will Be&lt;/li>\n  &lt;li>Numbered In&lt;/li>\n  &lt;li>Reverse&lt;/li>\n&lt;/ol></code></pre>\n\n\n\n<p>For most people, this would be enough. Job done.&nbsp;</p>\n\n\n\n<p>But I needed <strong>custom styles</strong> for the counters.&nbsp;</p>\n\n\n\n<p>Let it be known that custom list number styles can be done with <a href=\"https://css-tricks.com/almanac/selectors/m/marker/\">the <code>::marker</code> pseudo-element</a>, but that isn’t yet supported by Chrome (although I hear it’s coming soon).</p>\n\n\n\n<p>Because I wanted fully cross-browser compatible custom number styles, I went with custom counters.&nbsp;</p>\n\n\n\n<h3>Adding and styling a custom counter</h3>\n\n\n\n<p>Styling the counters of an ordered list differently from the rest of the list requires disabling the default counters and creating and show our own using <a href=\"https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_Lists_and_Counters/Using_CSS_counters\">CSS Counters</a>. Chris <a href=\"https://css-tricks.com/custom-list-number-styling/\">shared a few recipes</a> a while back that are worth checking out.</p>\n\n\n\n<p>Assuming we have the following HTML:</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">&lt;ol class=\"fancy-numbered\">\n  &lt;li>Item 1&lt;/li>\n  &lt;li>Item 2&lt;/li>\n  &lt;li>Item 3&lt;/li>\n&lt;/ol></code></pre>\n\n\n\n<p>…we first need to disable the default counters that come with all ordered lists by setting the CSS property <code>list-style-type</code> to <code>none</code> like so:</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">ol.fancy-numbered {\n  list-style-type: none;\n}</code></pre>\n\n\n\n<p>That takes out all the default numbering. Next, we create a counter in CSS to track the number of items in the list.</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">ol.fancy-numbered {\n  list-style-type: none;\n  counter-reset: a;\n}</code></pre>\n\n\n\n<p>This gives us a counter named &#8220;a&#8221; but it can be called it whatever you like. Let&#8217;s display our counter using the <code>::before</code> <a href=\"https://developer.mozilla.org/en-US/docs/Web/CSS/Pseudo-elements\">pseudo-element</a> on the list item (<code>&lt;li&gt;</code>).</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">ol.fancy-numbered li::before {\n  content: counter(a)\'.\';\n}</code></pre>\n\n\n\n<p>This will set the content of the pseudo-element to the value of our counter. Right now, that will print 1&#8217;s next to your list item.</p>\n\n\n\n<p>We need to tell the CSS counter how to increment.</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">ol.fancy-numbered li::before {\n  content: counter(a)\'.\';\n  counter-increment: a;\n}</code></pre>\n\n\n\n<p>The starting value of “a” is zero, which seems weird, but the default increment is 1, meaning that becomes the actual starting point. &nbsp;Incrementing up by 1 just happens to be the default, but we can change that as we’ll soon see.</p>\n\n\n\n<p>We can now proceed to apply any custom styles we want to the counter, because the counter is just a text pseudo-element that is wide open to styling:</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">ol.fancy-numbered li::before {\n  content: counter(a)\'.\';\n  counter-increment: a;   \n  position: absolute;   \n  left: 0;   \n  color: blue;   \n  font-size: 4rem;\n}</code></pre>\n\n\n\n<p>For example, here, we&#8217;ve made the counter color blue and increased the font size. These are things that we couldn&#8217;t do using the default counter.</p>\n\n\n\n<h3>Reversing custom counters</h3>\n\n\n\n<p>If we add the <code>reversed</code> property to the <code>&lt;ol&gt;</code> element like we did before, we will observe no effect because we disabled the default numbering. That’s just what this property does.</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">&lt;ol class=\"fancy-numbered\" reversed>\n  &lt;li>Item 1&lt;/li>\n  &lt;li>Item 2&lt;/li>\n  &lt;li>Item 3&lt;/li>\n&lt;/ol></code></pre>\n\n\n\n<p>The code above has no effect on our custom numbering. It’s still probably a good idea to leave it on there, since our intention is to reverse the list. This keeps things semantically accurate.</p>\n\n\n\n<p>To reverse the visual order of our counter-based numbering, we need to know the total number of items in the list and instruct the counter to start from that number and then decrement from there.</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">ol.fancy-numbered {\n  counter-reset: a 4;\n  list-style-type: none;\n}</code></pre>\n\n\n\n<p>Here, we’re setting <code>counter-reset</code> to 4. In other words, we’re telling the browser to start the count at 4 instead of 1. We use 4 instead of 3, again, because the <code>counter()</code> rule is applied to the first item on the list, which is 0. But, in the case where we’re counting backwards, 4 becomes our 0. If we started from 3 and decremented, wind up at 0 instead of 1.</p>\n\n\n\n<p>Next, we alter our <code>counter-increment</code> rule to <em>decrease</em> by 1 rather than increase, by making it a <em>negative integer</em>.</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"3\"><code markup=\"tt\">ol.fancy-numbered li:before {\n  content: counter(a)\'.\';\n  counter-increment: a -1;\n  position: absolute;   \n  left: 0;   \n  color: blue;   \n  font-size: 4rem;\n}</code></pre>\n\n\n\n<p>And that&#8217;s it! Now the world is your oyster for stuff like step trackers:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_ExPYvYM\" src=\"//codepen.io/anon/embed/ExPYvYM?height=450&amp;theme-id=1&amp;slug-hash=ExPYvYM&amp;default-tab=result\" height=\"450\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed ExPYvYM\" title=\"CodePen Embed ExPYvYM\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>Or how about a timeline:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_gOPYxbg\" src=\"//codepen.io/anon/embed/gOPYxbg?height=450&amp;theme-id=1&amp;slug-hash=gOPYxbg&amp;default-tab=result\" height=\"450\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed gOPYxbg\" title=\"CodePen Embed gOPYxbg\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>Maybe a <a href=\"https://youtu.be/3zc4bGkU05o\">business plan</a>?</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_dyGbRab\" src=\"//codepen.io/anon/embed/dyGbRab?height=450&amp;theme-id=1&amp;slug-hash=dyGbRab&amp;default-tab=result\" height=\"450\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed dyGbRab\" title=\"CodePen Embed dyGbRab\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/how-to-reverse-css-custom-counters/\">How to Reverse CSS Custom Counters</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 'Tips, Tricks, and Techniques on using Cascading Style Sheets.', 'basic_html');
INSERT INTO `node__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('feed_rss', 0, 1023, 1023, 'en', 0, '\n<p>Here’s the plan! We’re going to build a styled select element. Not just <a href=\"https://css-tricks.com/styling-a-select-like-its-2019/\">the outside</a>, but the inside too. Total styling control. Plus we’re going to make it accessible. We’re not going to try to <em>replicate</em> everything that the browser does by default with a native <code>&lt;select&gt;</code> element. We’re going to literally use a <code>&lt;select&gt;</code> element when any assistive tech is used. But when a mouse is being used, we’ll show the styled version and make it function as a select element.</p>\n\n\n\n<p>That’s what I mean by “hybrid” selects: they are both a native <code>&lt;select&gt;</code> and a styled alternate select in one design pattern.</p>\n\n\n\n<span id=\"more-312544\"></span>\n\n\n\n<figure class=\"wp-block-image size-large\"><img src=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-5.png?fit=1024%2C509&amp;ssl=1\" alt=\"\" class=\"wp-image-312546\" srcset=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-5.png?w=1784&amp;ssl=1 1784w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-5.png?resize=300%2C149&amp;ssl=1 300w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-5.png?resize=1024%2C509&amp;ssl=1 1024w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-5.png?resize=768%2C382&amp;ssl=1 768w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-5.png?resize=1536%2C764&amp;ssl=1 1536w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-5.png?resize=1000%2C497&amp;ssl=1 1000w\" sizes=\"(min-width: 735px) 864px, 96vw\" /><figcaption>Custom selects (left) are often used in place of native selects (right) for aesthetics and design consistency.</figcaption></figure>\n\n\n\n<h3>Select, dropdown, navigation, menu… the name matters</h3>\n\n\n\n<p>While doing the research for this article, I thought about many names that get tossed around when talking about selects, the most common of which are “dropdown” and “menu.” There are two types of naming mistakes we could make: giving the <em>same</em> name to different things, or giving <em>different</em> names to the same thing. A select can suffer from both mistakes.</p>\n\n\n\n<p>Before we move ahead, let me try to add clarity around using “dropdown” as a term. Here’s how I define the meaning of dropdown:</p>\n\n\n\n<blockquote class=\"wp-block-quote\"><p><strong>Dropdown: </strong>An interactive component that consists of a button that shows and hides a list of items, typically on mouse hover, click or tap. The list is not visible by default until the interaction starts. The list usually displays a block of content (i.e. options) on top of other content.</p></blockquote>\n\n\n\n<p>A lot of interfaces can look <em>like</em> a dropdown. But simply calling an element a “dropdown&#8221; is like using “fish” to describe an animal. What type of fish it is? A clownfish is not the same as a shark. The same goes for dropdowns.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img src=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-2.jpeg?fit=1024%2C640&amp;ssl=1\" alt=\"\" class=\"wp-image-312549\" srcset=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-2.jpeg?w=1920&amp;ssl=1 1920w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-2.jpeg?resize=300%2C188&amp;ssl=1 300w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-2.jpeg?resize=1024%2C640&amp;ssl=1 1024w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-2.jpeg?resize=768%2C480&amp;ssl=1 768w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-2.jpeg?resize=1536%2C960&amp;ssl=1 1536w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-2.jpeg?resize=1000%2C625&amp;ssl=1 1000w\" sizes=\"(min-width: 735px) 864px, 96vw\" /></figure>\n\n\n\n<p>Like there are different types of fish in the sea, there are different types of components that we might be talking about when we toss the word “dropdown” around:</p>\n\n\n\n<ul><li><strong>Menu: </strong>A list of commands or actions that the user can perform within the page content.</li><li><strong>Navigation:</strong> A list of links used for navigating through a website.</li><li><strong>Select: </strong>A form control (<code>&lt;select&gt;</code>) that displays a list of options for the user to select within a form.</li></ul>\n\n\n\n<p>Deciding what type of dropdown we’re talking about can be a foggy task. Here are some examples from around the web that match how I would classify those three different types. This is based on my research and sometimes, when I can’t find a proper answer, <em>intuition</em> based on my experience.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img src=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-9.png?fit=1024%2C638&amp;ssl=1\" alt=\"\" class=\"wp-image-312552\" srcset=\"https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-9.png?w=1864&amp;ssl=1 1864w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-9.png?resize=300%2C187&amp;ssl=1 300w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-9.png?resize=1024%2C638&amp;ssl=1 1024w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-9.png?resize=768%2C479&amp;ssl=1 768w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-9.png?resize=1536%2C958&amp;ssl=1 1536w, https://i1.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-9.png?resize=1000%2C623&amp;ssl=1 1000w\" sizes=\"(min-width: 735px) 864px, 96vw\" /><figcaption>Dropdown-land: Five scenarios where different dropdowns are used across the internet. Read the table below for a detailed description.</figcaption></figure>\n\n\n\n<figure class=\"wp-block-table\"><table><thead><tr><th>Diagram Label</th><th>Scenario</th><th>Dropdown Type</th></tr></thead><tbody><tr><td>1</td><td>The dropdown expects a selected option to be submitted within a form context (e.g. Select Age)</td><td>Select</td></tr><tr><td>2</td><td>The dropdown does not need an active option (e.g. A list of actions: copy, paste and cut)</td><td>Menu</td></tr><tr><td>3</td><td>The selected option influences the content. (e.g. sorting list)</td><td>Menu or Select (more about it later)</td></tr><tr><td>4</td><td>The dropdown contains links to other pages. (e.g. A “meganav” with websites links)</td><td><a href=\"https://www.w3.org/TR/wai-aria-practices/examples/disclosure/disclosure-navigation.html\">Disclosure Navigation</a></td></tr><tr><td>5</td><td>The dropdown has content that is not a list. (e.g. a date picker)</td><td>Something else that should not be called dropdown</td></tr></tbody></table></figure>\n\n\n\n<p>Not everyone perceives and interacts with the internet in the same way. Naming user interfaces and defining design patterns is a fundamental process, though one with a lot of room for personal interpretation. All of that variation is what drives the population of dropdown<em>-land.&nbsp;</em></p>\n\n\n\n<p>There is a dropdown type that is clearly a <strong>menu. </strong>Its usage is a hot topic in conversations about accessibility. I won’t talk much about it here, but let me just reinforce that the <a href=\"https://developer.mozilla.org/en-US/docs/Web/HTML/Element/menu\"><code>&lt;menu&gt;</code></a> element is deprecated and no longer recommended. And here’s a detailed explanation about <a href=\"https://inclusive-components.design/menus-menu-buttons/\">inclusive menus and menus buttons</a>, including why <a href=\"https://adrianroselli.com/2017/10/dont-use-aria-menu-roles-for-site-nav.html\">ARIA menu role should not be used for site navigation</a>.</p>\n\n\n\n<p>We haven’t even touched on other elements that fall into a rather gray area that makes classifying dropdowns even murkier because of a lack of practical uses cases from the WCAG community.</p>\n\n\n\n<p>Uff… that was a lot. Let’s forget about this dropdown-land mess and focus exclusively on the dropdown type that is clearly a <code>&lt;select&gt;</code> element.</p>\n\n\n\n<h3>Let’s talk about <code>&lt;select&gt;</code></h3>\n\n\n\n<p>Styling form controls is an interesting journey. As MDN puts it, there’s <a href=\"https://developer.mozilla.org/en-US/docs/Learn/Forms/Styling_web_forms#Why_is_styling_form_widgets_challenging\"><em>the good, the bad, and the ugly</em></a>. Good is stuff like <code>&lt;form&gt;</code> which is just a block-level element to style. Bad is stuff like checkboxes, which <a href=\"https://css-tricks.com/custom-styling-form-inputs-with-modern-css-features/\">can be done but is somewhat cumbersome</a>. <code>&lt;select&gt;</code> is definitely in ugly terrain.</p>\n\n\n\n<p>A lot of articles have been written about it and, even in 2020, <a href=\"https://css-tricks.com/making-a-better-custom-select-element/\">it’s still a challenge to create custom selects</a> and <a href=\"https://www.24a11y.com/2019/select-your-poison-part-2/\">some users still prefer the simple native ones</a>.&nbsp;</p>\n\n\n\n<p>Among developers, the <code>&lt;select&gt;</code> is the <a href=\"https://www.gwhitworth.com/blog/2019/07/form-controls-components/\">most frustrating form control by far</a>, mainly because of <a href=\"https://www.gwhitworth.com/blog/2019/10/can-we-please-style-select/\">its lack of styling support</a>. The UX struggle behind it is so big that we <a href=\"https://medium.com/@kollinz/dropdown-alternatives-for-better-mobile-forms-53e40d641b53\">look for other alternatives</a>. Well, I guess the first rule of <code>&lt;select&gt;</code> is <a href=\"https://www.w3.org/TR/using-aria/%23firstrule\">similar to ARIA</a>: <strong>avoid using it if you can.</strong></p>\n\n\n\n<p>I could finish the article right here with <em>“Don’t use <code>&lt;select&gt;</code>, period.&#8221;</em> But let’s face reality: a select is still our best solution in a number of circumstances. That might include scenarios where&nbsp;we’re working with a list that contains a lot of options, layouts that are tight on space, or simply a lack of time or budget to design and implement a great custom interactive component from scratch.</p>\n\n\n\n<h3>Custom <code>&lt;select&gt;</code> requirements</h3>\n\n\n\n<p>When we make the decision to create a custom select — even if it’s just a “simple” one — these are the requirements we generally have to work with:</p>\n\n\n\n<ul><li>There is a button that contains the current selected option.</li><li>Clicking the box toggles the visibility of the options list (also called listbox).</li><li>Clicking an option in the listbox updates the selected value. The button text changes and the listbox is closed.</li><li>Clicking outside the component closes the listbox.</li><li>The trigger contains a small triangle icon pointing downward to indicate there are options.</li></ul>\n\n\n\n<p>Something like this:</p>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_dyYqmya\" src=\"//codepen.io/anon/embed/dyYqmya?height=575&amp;theme-id=1&amp;slug-hash=dyYqmya&amp;default-tab=result\" height=\"575\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed dyYqmya\" title=\"CodePen Embed dyYqmya\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<p>Some of you may be thinking this works and is good to go. But wait… does it work for <em>everyone</em>? &nbsp;Not everyone uses a mouse (or touch screen). Plus, a native <code>&lt;select&gt;</code> element comes with more features we get for free and aren&#8217;t included in those requirements, such as:</p>\n\n\n\n<ul><li>The checked option is perceivable for all users regardless of their visual abilities.</li><li>The component can interact with a keyboard in a predictable way across all browsers (e.g. using arrow keys to navigate, <code>Enter</code> to select, <code>Esc</code> to cancel, etc.).</li><li>Assistive technologies (e.g. screen readers) announce the element clearly to users, including its role, name and state.</li><li>The listbox position is adjusted. (i.e. does not get cut off of the screen).</li><li>The element respects the user’s operating system preferences (e.g high contrast, color scheme, motion, etc.).</li></ul>\n\n\n\n<p>This is where the majority of the custom selects fail in some way. Take a look at some of the major UI components libraries. I won’t mention any because the web is ephemeral, but go give it a try. You’ll likely notice that the select component in one framework behaves differently from another.&nbsp;</p>\n\n\n\n<p>Here are additional characteristics to watch for:</p>\n\n\n\n<ul><li>Is a listbox option immediately activated on focus when navigating with a keyboard?</li><li>Can you use <code>Enter</code> and/or <code>Space</code> to select an option?</li><li>Does the <code>Tab</code> key jump go to the next option in the listbox, or jump to the next form control?</li><li>What happens when you reach the last option in the listbox using arrow keys? Does it simply stay at the last item, does it go back to the first option, or worst of all, does focus move to the next form control?&nbsp;</li><li>Is it possible to jump directly to the last item in the listbox using the <code>Page Down</code> key?</li><li>Is it possible to scroll through the listbox items if there are more than what is currently in view?</li></ul>\n\n\n\n<p>This is a small sample of the features included in a native <code>&lt;select&gt;</code> element. </p>\n\n\n\n<blockquote class=\"wp-block-quote\"><p>Once we decide to create our own custom select, we are forcing people to use it in a certain way that may not be what they expect.</p></blockquote>\n\n\n\n<p>But it gets worse. Even the native <code>&lt;select&gt;</code> <a href=\"https://www.24a11y.com/2019/select-your-poison/\">behaves differently</a> across browsers and screen readers. Once we decide to create our own custom select, we are forcing people to use it in a certain way that may not be what they expect. That’s a dangerous decision and it’s in those details where the devil lives.</p>\n\n\n\n<h3>Building a “hybrid” select</h3>\n\n\n\n<p>When we build a simple custom select, we are making a trade-off without noticing it. Specifically, <strong>we sacrifice functionality to aesthetics. </strong>It should be the other way around.</p>\n\n\n\n<p>What if we instead deliver a native select by default and replace it with a more aesthetically pleasing one if possible? That’s where the “hybrid” select idea comes into action. It’s “hybrid” because it consists of two selects, showing the appropriate one at the right moment:</p>\n\n\n\n<ul><li>A native select, visible and accessible by default</li><li>A custom select, hidden until it’s safe to be interacted with a mouse</li></ul>\n\n\n\n<p>Let’s start with markup. First, we’ll add a native <code>&lt;select&gt;</code> with <code>&lt;option&gt;</code> items <em>before</em> the custom selector for this to work. (I’ll explain why in just a bit.)</p>\n\n\n\n<p>Any form control must have a <a href=\"https://www.w3.org/WAI/tutorials/forms/labels/\">descriptive label</a>. We could use <code>&lt;label&gt;</code>, but that would focus the native select when the label is clicked. To prevent that behavior, we’ll use a <code>&lt;span&gt;</code> and connect it to the select using <code>aria-labelledby</code>.</p>\n\n\n\n<p>Finally, we need to tell Assistive Technologies to ignore the custom select, using <code>aria-hidden=\"true\"</code>. That way, only the native select is announced by them, no matter what.</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"3,4,5,6\"><code markup=\"tt\">&lt;span class=\"selectLabel\" id=\"jobLabel\">Main job role&lt;/span>\n&lt;div class=\"selectWrapper\">\n  &lt;select class=\"selectNative js-selectNative\" aria-labelledby=\"jobLabel\">\n    &lt;!-- options -->\n    &lt;option>&lt;/option>\n  &lt;/select>\n  &lt;div class=\"selectCustom js-selectCustom\" aria-hidden=\"true\">\n     &lt;!-- The beautiful custom select -->\n  &lt;/div>\n&lt;/div></code></pre>\n\n\n\n<p>This takes us to styling, where we not only make things look pretty, but where we handle the switch from one select to the other. We need just a few new declarations to make all the magic happen.</p>\n\n\n\n<p>First, both native and custom selects must have the same width and height. This ensures people don’t see major differences in the layout when a switch happens.</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">.selectNative,\n.selectCustom {\n  position: relative;\n  width: 22rem;\n  height: 4rem;\n}</code></pre>\n\n\n\n<p>There are two selects, but only one can dictate the space that holds them. The other needs to be absolutely positioned to take it out of the document flow. Let’s do that to the custom select because it’s the “replacement” that’s used only if it can be. We’ll hide it by default so it can’t be reached by anyone just yet.</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">.selectCustom {\n  position: absolute;\n  top: 0;\n  left: 0;\n  display: none;\n}</code></pre>\n\n\n\n<p>Here comes the &#8220;funny” part. We need to detect if someone is using a device where hover is part of the primary input, like a computer with a mouse. While we typically think of media queries for responsive breakpoints or checking feature support, we can use it to detect hover support too using <code>@media query (hover :hover)</code>, which is supported by all major browsers. So, let&#8217;s use it to show the custom select only on devices that have hover:</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">@media (hover: hover) {\n  .selectCustom {\n    display: block;\n  }\n}</code></pre>\n\n\n\n<p>Great, but what about people who use a keyboard to navigate even in devices that have hover? What we’ll do is hide the custom select when the native select is in focus. We can reach for an <a href=\"https://developer.mozilla.org/en-US/docs/Web/CSS/Adjacent_sibling_combinator\">adjacent Sibling combinatioron</a> (<code>+</code>). When the native select is in focus, hide the custom select next to it in the DOM order. (This is why the native select should be placed before the custom one.)</p>\n\n\n\n<pre rel=\"CSS\" class=\"wp-block-csstricks-code-block language-css\" data-line=\"\"><code markup=\"tt\">@media (hover: hover) {\n  .selectNative:focus + .selectCustom {\n    display: none;\n  }\n}</code></pre>\n\n\n\n<p>That’s it! The trick to switch between both selects is done! There are other CSS ways to do it, of course, but this works nicely.</p>\n\n\n\n<p>Last, we need a sprinkle of JavaScript. Let’s add some event listeners:</p>\n\n\n\n<ul><li>One for click events that trigger the custom select to open and reveal the options</li><li>One to sync both selects values. When one select value is changed, the other select value updates as well</li><li>One for basic keyboard navigation controls, like navigation with <code>Up</code> and <code>Down</code> keys, selecting options with the <code>Enter</code> or <code>Space</code> keys, and closing the select with <code>Esc</code></li></ul>\n\n\n\n<div class=\"wp-block-cp-codepen-gutenberg-embed-block cp_embed_wrapper\"><iframe id=\"cp_embed_YzyOYRr\" src=\"//codepen.io/anon/embed/YzyOYRr?height=575&amp;theme-id=1&amp;slug-hash=YzyOYRr&amp;default-tab=result\" height=\"575\" scrolling=\"no\" frameborder=\"0\" allowfullscreen allowpaymentrequest name=\"CodePen Embed YzyOYRr\" title=\"CodePen Embed YzyOYRr\" class=\"cp_embed_iframe\" style=\"width:100%;overflow:hidden\">CodePen Embed Fallback</iframe></div>\n\n\n\n<h3>Usability testing</h3>\n\n\n\n<p>I conducted a very small usability test where I asked a few people with disabilities to try the hybrid select component. The following devices and tools were tested using the latest versions of Chrome (81), Firefox (76) and Safari (13):</p>\n\n\n\n<ul><li>Desktop device using mouse only</li><li>Desktop device using keyboard only</li><li>VoiceOver on MacOS using keyboard</li><li>NVDA on Windows using keyboard</li><li>VoiceOver on iPhone and iPad using Safari</li></ul>\n\n\n\n<p>All these tests worked as expected, but I believe <strong>this could have even more usability tests with more diverse people and tools</strong>. If you have access to other devices or tools — such as JAWS, Dragon, etc. — please tell me how the test goes.</p>\n\n\n\n<p>An issue was found during testing. Specifically, the issue was with the VoiceOver setting “Mouse pointers: Moves Voice Over cursor.” If the user opens the select with a mouse, the custom select will be opened (instead of the native) and the user won’t experience the native select.</p>\n\n\n\n<p>What I most like about this approach is how it uses the best of both worlds without compromising the core functionality:</p>\n\n\n\n<ul><li>Users on mobile and tablets get the native select, which generally offers a better user experience than a custom select, including performance benefits.</li><li>Keyboard users get to interact with the native select the way they would expect.</li><li>Assistive Technologies can interact with the native select like normal.</li><li>Mouse users get to interact with the enhanced custom select.</li></ul>\n\n\n\n<p>This approach<strong> provides essential native functionality for everyone </strong>without the extra huge code effort to implement all the native features.</p>\n\n\n\n<p>Don’t get me wrong. This technique is not a one-size-fits-all solution. It may work for simple selects but probably won’t work for cases that involve complex interactions. In those cases, we’d need to use ARIA and JavaScript to complement the gaps and create a <a href=\"https://24ways.org/2019/making-a-better-custom-select-element/\">truly accessible custom select</a>.</p>\n\n\n\n<h3>A note about selects that look like menus</h3>\n\n\n\n<p>Let’s take a look back at the third Dropdown-land scenario. If you recall, it’s &nbsp;a dropdown that always has a checked option (e.g. sorting some content). I classified it in the gray area, as either a menu or a select.&nbsp;</p>\n\n\n\n<p>Here’s my line of thought: Years ago, this type of dropdown was implemented mostly using a native <code>&lt;select&gt;</code>. Nowadays, it is common to see it implemented from scratch with custom styles (accessible or not). What we end up with is a select element that looks like a menu.&nbsp;</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img src=\"https://i2.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-11.png?ssl=1\" alt=\"Three similar dropdowns that always have a selected option.\" class=\"wp-image-312555\" srcset=\"https://i2.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-11.png?w=718&amp;ssl=1 718w, https://i2.wp.com/css-tricks.com/wp-content/uploads/2020/06/image-11.png?resize=300%2C119&amp;ssl=1 300w\" sizes=\"(min-width: 735px) 864px, 96vw\" data-recalc-dims=\"1\" /></figure>\n\n\n\n<p><strong>A <code>&lt;select&gt;</code> &nbsp;is a type of menu.</strong> Both have similar semantics and behavior, especially in a scenario that involves a list of options where one is always checked. &nbsp;Now, let me mention the <a href=\"https://www.w3.org/WAI/WCAG21/Understanding/on-input.html\">WCAG 3.2.2 On Input (Level A)</a> criterion:</p>\n\n\n\n<blockquote class=\"wp-block-quote\"><p>Changing the setting of any user interface component should not automatically cause a change of context unless the user has been advised of the behavior before using the component.</p></blockquote>\n\n\n\n<p>Let’s put this in practice. Imagine a sortable list of students. Visually, it may be obvious that sorting is immediate, but that’s not necessarily true for everyone. So, when using <code>&lt;select&gt;</code>, we risk failing the WCAG guideline because the page content changed, and ignificantly re-arranging the content of a page is considered a <a href=\"https://www.w3.org/WAI/WCAG21/Understanding/on-input.html%23dfn-changes-of-context\">change of context</a>.</p>\n\n\n\n<p>To ensure the criterion success, we must warn the user about the action before they interact with the element, or include a <code>&lt;button&gt;</code> immediately after the select to confirm the change.</p>\n\n\n\n<pre rel=\"HTML\" class=\"wp-block-csstricks-code-block language-markup\" data-line=\"\"><code markup=\"tt\">&lt;label for=\"sortStudents\">\n  Sort students\n  &lt;!-- Warn the user about the change when a confirmation button is not present. -->\n  &lt;span class=\"visually-hidden\">(Immediate effect upon selection)&lt;/span>\n&lt;/label>\n&lt;select id=\"sortStudents\"> ... &lt;/select></code></pre>\n\n\n\n<p>That said, using a <code>&lt;select&gt;</code> or building a custom menu are both good approaches when it comes to simple menus that change the page content. Just remember that your decision will dictate the amount of work required to make the component fully accessible. This is a scenario where the hybrid select approach could be used.</p>\n\n\n\n<h3>Final words</h3>\n\n\n\n<p>This whole idea started as an innocent CSS trick but, after all of this research, I was reminded once more that creating unique experiences without compromising accessibility is not an easy task.</p>\n\n\n\n<p>Building truly accessible select components (or any kind of dropdown) is harder than it looks. WCAG provides excellent guidance and best practices, but without specific examples and diverse practical uses cases, the guidelines are mostly aspirational. That’s not to mention the fact that ARIA support is tepid and that native <code>&lt;select&gt;</code> elements look and behave differently across browsers.</p>\n\n\n\n<p>The “hybrid” select is just another attempt to create a good looking select while getting as many native features as possible. Don’t look at this <s>technique</s> experiment as an excuse to downplay accessibility, but rather as an attempt to serve both worlds. If you have the resources, time and the needed skills, <em>please do it right</em> and make sure to test it with different users before shipping your component to the world.</p>\n\n\n\n<p>P.S. Remember to <a href=\"https://adrianroselli.com/2020/03/stop-using-drop-down.html\">use a proper name</a> when making a “dropdown” component. &#x1f609;</p>\n<p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/striking-a-balance-between-native-and-custom-select-elements/\">Striking a Balance Between Native and Custom Select Elements</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 'Tips, Tricks, and Techniques on using Cascading Style Sheets.', 'basic_html'),
('feed_rss', 0, 1024, 1024, 'en', 0, '\n<p>There are some neat interactive demos <a href=\"https://thirumanikandan.com/posts/learn-z-index-using-a-visualization-tool\">in here</a> from Thiru Manikandan. There are a couple of very tricky things with <code><a href=\"https://css-tricks.com/almanac/properties/z/z-index/\">z-index</a></code> that never fail to confuse. In addition to things like requiring positioning and source order, the trickiest are the stacking contexts and parent/child relationships. <code>z-index</code> isn&#8217;t a flat playing field. Even if you put <code>z-index: 2147483644</code><a href=\"#fn:1\">¹</a> on an element, it&#8217;s possible nothing will happen because that element might be inside a parent element with its own stacking context and a lower <code>z-index</code> than a sibling or some higher-up level DOM element.</p>\n\n\n\n<div class=\"wp-block-group footnotes\" id=\"fn:1\"><div class=\"wp-block-group__inner-container\">\n<ol><li>Just three shy of the maximum 2147483647. LOLZ. Hat tip to Dan Danney who mentioned seeing that in the wild recently. </li></ol>\n</div></div>\n\n\n\n<p></p>\n<p><a href=\"https://thirumanikandan.com/posts/learn-z-index-using-a-visualization-tool\" title=\"Direct link to featured article\">Direct Link to Article</a> &#8212; <a href=\"https://css-tricks.com/learn-z-index-using-a-visualization-tool/\">Permalink</a></p><p>The post <a rel=\"nofollow\" href=\"https://css-tricks.com/learn-z-index-using-a-visualization-tool/\">Learn Z-Index Using a Visualization Tool</a> appeared first on <a rel=\"nofollow\" href=\"https://css-tricks.com\">CSS-Tricks</a>.</p>\n', 'Tips, Tricks, and Techniques on using Cascading Style Sheets.', 'basic_html');
INSERT INTO `node__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('feed_rss', 0, 1025, 1025, 'en', 0, '\n          <html>\n            <head>\n              <meta charset=\"utf-8\">\n              <link rel=\"canonical\" href=\"https://www.smashingmagazine.com/2020/06/internationalization-vue-i18n/\" />\n              <title>Internationalization In Vue With The Vue I18n Plugin</title>\n            </head>\n            <body>\n              <article>\n                <header>\n                  <h1>Internationalization In Vue With The Vue I18n Plugin</h1>\n                  \n                    \n                    <address>Timi Omoyeni</address>\n                  \n                  <time datetime=\"2020-06-12T10:00:00&#43;00:00\" class=\"op-published\">2020-06-12T10:00:00+00:00</time>\n                  <time datetime=\"2020-06-12T10:00:00&#43;00:00\" class=\"op-modified\">2020-06-13T10:05:58+00:00</time>\n                </header>\n                \n\n<p>Building applications for people from different parts of the world comes with challenges like support for multiple locales and how to integrate it into your application. I remember the first time I faced this challenge, I had to build an application that was going to have multiple languages (English, Yoruba, and French). This was the first time I ever wondered how applications that supported multiple languages were built and also how I discovered “Internationalization”.</p>\n\n<p>In this tutorial, we’re going to learn about Internationalization and how to implement it in our Vue application using the Vue I18n plugin by building a simple app that uses this plugin. This plugin helps you configure your application to work with multiple locales and allows your user to choose between all the available locales without you having to do too much.</p>\n\n<p>I have put together a simple application for the purpose of this tutorial and it can be found on <a href=\"https://github.com/Timibadass/vue-i18n-app\">Github</a>.</p>\n\n<p><em>This article requires basic knowledge of the Vue.js framework. For those looking to get started with Vuejs, I recommend you start from their</em> <a href=\"http://vuejs.org/\"><em>official documentation</em></a><em>.</em></p>\n\n<div class=\"c-felix-the-cat\">\n<h4>React Internationalization</h4>\n<p>How can we build an internationalized React front-end application? Yury Dymov explains how you can detect the user’s locale, save it in the cookie, let the user change their locale, translate the user interface, and render currencies in their appropriate formats. <a href=\"https://www.smashingmagazine.com/2017/01/internationalizing-react-apps/\" class=\"btn btn--small btn--white btn--white--bordered\">Read article&nbsp;&rarr;</a></p>\n</div>\n\n\n  <div data-component=\"FeaturePanel\" data-audience=\"non-subscriber\" data-remove=\"true\" class=\"feature-panel-container hidden\"></div>\n\n\n<h3 id=\"what-are-i18n-and-vue-i18n\">What Are i18n And Vue-i18n?</h3>\n\n<h4 id=\"internationalization-i18n\">Internationalization (i18n)</h4>\n\n<p>Internationalization (sometimes shortened to &ldquo;I18N, meaning &ldquo;I &mdash; eighteen letters &mdash; N&rdquo;) is the process of planning and implementing products and services so that they can easily be adapted to specific local languages and cultures, a process called <a href=\"https://searchcio.techtarget.com/definition/localization\">localization</a>. Imagine you’re building a product for people in the USA and France, without internationalization, this would mean building two separate applications in different locales to run on different domains (English version on amazingproduct.us and French version on amazingproduct.fr).</p>\n\n<p>This is where Internationalization comes in. It helps people from both countries easily use the application in the locale of their choice (English or French). Internationalizing your application comes with benefits such as:</p>\n\n<ol>\n<li>Single source code for all languages of the product.</li>\n<li>Greater in-country customer acceptance and satisfaction.</li>\n<li>It makes the maintenance of the product easier and simpler.</li>\n<li>Reduced time, cost, and effort for localization (L10n).</li>\n</ol>\n\n<h4 id=\"internationalization-in-vue\">Internationalization in Vue</h4>\n\n<p>Internationalization can be implemented in Vue using the <em>Vue I18n</em> plugin. It easily integrates some localization features to your Vue.js application. It can be added to your application in one of the following ways:</p>\n\n<ul>\n<li>By direct download/CDN &mdash; using this <a href=\"https://unpkg.com/vue-i18n/dist/vue-i18n\">CDN link</a> for the latest release on NPM.</li>\n</ul>\n\n<p>After which it would be included in head section of your html file.</p>\n\n<pre><code class=\"language-html\">&lt;script src=\"https://unpkg.com/vue-i18n/dist/vue-i18n.js\"&gt;&lt;/script&gt;</code></pre>\n\n<ul>\n<li>By installing from NPM or Yarn.\n<br /></li>\n</ul>\n\n<pre><code class=\"language-bash\">npm install vue-i18n\n// or\nyarn add vue-i18n</code></pre>   \n\n<ul>\n<li>By adding it using the Vue Cli 3.x (You need Vue cli 3.x).\n<br /></li>\n</ul>\n\n<pre><code class=\"language-bash\">vue add i18n</code></pre>   \n\n<h3 id=\"setting-up-vue-i18n-in-your-app\">Setting Up Vue-i18n In Your App</h3>\n\n<p>To set this plugin up in your application, we’re going to use the Vue CLI method. That can be done using this command:</p>\n\n<pre><code class=\"language-bash\">vue add i18n</code></pre>   \n\n<p>On running this command, you would be prompted to select config options to choose from. For this tutorial, I’ve gone ahead to select all the default options for setting up this plugin. This looks like this:</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n    break-out article__image\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/2e5e4f1c-0886-4d91-9c43-02b6b017c8c8/01-config.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/2e5e4f1c-0886-4d91-9c43-02b6b017c8c8/01-config.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/2e5e4f1c-0886-4d91-9c43-02b6b017c8c8/01-config.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/2e5e4f1c-0886-4d91-9c43-02b6b017c8c8/01-config.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/2e5e4f1c-0886-4d91-9c43-02b6b017c8c8/01-config.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/2e5e4f1c-0886-4d91-9c43-02b6b017c8c8/01-config.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/2e5e4f1c-0886-4d91-9c43-02b6b017c8c8/01-config.png\"\n			sizes=\"100vw\"\n			alt=\"config options for Vue I18n plugin.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Config options for Vue I18n plugin. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/2e5e4f1c-0886-4d91-9c43-02b6b017c8c8/01-config.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<p>Let’s take a look at what they do:</p>\n\n<ol>\n<li>The first option is to set the default locale the application would be in and in this case, I have gone ahead to set it to English.</li>\n<li>The second option is to set a fallback locale for the application and fallback is going to serve as a backup locale for your application if you fail to provide a translation in another locale and I selected English. This would be talked about later on in this article.</li>\n<li>The third option is for choosing a directory for storing all the <strong>locale</strong> json files to be used for localization in the app and I selected the default option which is <strong>locales.</strong></li>\n<li>The last option is for enabling component-based localization in Single File Components. This means deciding whether or not you want to enable translation inside a component and I enabled it in my configuration. We would talk about this later on in the article.</li>\n</ol>\n\n<p>Once this is done, your plugin would be configured to work in your app and you would be notified of some extra files that this plugin has added to your app.</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n    break-out article__image\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/02cd59e9-7d78-47aa-8653-7bb9d7559ecb/02-config-files.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/02cd59e9-7d78-47aa-8653-7bb9d7559ecb/02-config-files.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/02cd59e9-7d78-47aa-8653-7bb9d7559ecb/02-config-files.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/02cd59e9-7d78-47aa-8653-7bb9d7559ecb/02-config-files.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/02cd59e9-7d78-47aa-8653-7bb9d7559ecb/02-config-files.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/02cd59e9-7d78-47aa-8653-7bb9d7559ecb/02-config-files.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/02cd59e9-7d78-47aa-8653-7bb9d7559ecb/02-config-files.png\"\n			sizes=\"100vw\"\n			alt=\"A list of files added/modified by the plugin.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Vue-i18n config files. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/02cd59e9-7d78-47aa-8653-7bb9d7559ecb/02-config-files.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<p>Let us take a look at some of the files that were added to our app so we can understand their purpose:</p>\n\n<h4 id=\"locales-folder\">/locales folder</h4>\n\n<p>This folder serves as a base for all the locales that would be used in our app. If you open this folder, you will find an <strong>en.json</strong> file and this is because <code>en</code> was my selected locale for this project. What this means is that the file you will find inside your locale folder is dependent on your choice while setting up the plugin.</p>\n\n<h4 id=\"locales-en-json\">/locales/en.json</h4>\n\n<p>This file is for adding texts in the particular locale(file name e.g en, fr) so that when a user switches to that locale, your app fetches all your texts from the JSON file that matches the locale. By default, this file contains one property that serves as a demo for setting up your application, it looks like this:</p>\n\n<pre><code class=\"language-javascript\">{\n  \"message\": \"hello i18n !!\"\n}</code></pre>\n\n<p>Here, we have a <code>message</code> property that we can use anywhere in our file using this format:</p>\n\n<pre><code class=\"language-javascript\">&lt;p&gt; {{ $t(\'message\') }}</code></pre>\n\n<p>if we view this in our browser, what we would see would be the value of <code>message</code> and not <em>&ldquo;message&rdquo;.</em></p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n    break-out article__image\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b90bbaf1-565b-4f7c-ac30-efbb07c1f3cf/03-plugin-text.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b90bbaf1-565b-4f7c-ac30-efbb07c1f3cf/03-plugin-text.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b90bbaf1-565b-4f7c-ac30-efbb07c1f3cf/03-plugin-text.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b90bbaf1-565b-4f7c-ac30-efbb07c1f3cf/03-plugin-text.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b90bbaf1-565b-4f7c-ac30-efbb07c1f3cf/03-plugin-text.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b90bbaf1-565b-4f7c-ac30-efbb07c1f3cf/03-plugin-text.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b90bbaf1-565b-4f7c-ac30-efbb07c1f3cf/03-plugin-text.png\"\n			sizes=\"100vw\"\n			alt=\"Hello i18n.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      What vue-i18n displays in the browser. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b90bbaf1-565b-4f7c-ac30-efbb07c1f3cf/03-plugin-text.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<p>Now if you change the value of <code>message</code> in your file, it would be updated in your browser accordingly.</p>\n\n<div class=\"sponsors__lead-place\"></div>\n\n\n\n\n<h4 id=\"helloi18n-vue\">HelloI18n.vue</h4>\n\n<p>This file serves as an example of how to use the plugin in <a href=\"https://vuejs.org/v2/guide/single-file-components.html\">Single File Components</a>. If you inspect the file, you would find a <code>&lt;i18n&gt;</code> tag in the script section of this component. According to the documentation you would need to install <a href=\"https://github.com/kazupon/vue-i18n-loader\">vue-i18n-loader</a> to use this tag but you do not have to worry about this if you added it as a config option when installing the plugin. Inside this tag, we have an object which contains <code>en</code> (or your default locale) property which has a <code>hello</code> property with a value. This looks like this:</p>\n\n<pre><code class=\"language-javascript\">&lt;i18n&gt;\n{\n  \"en\": {\n    \"hello\": \"Hello i18n in SFC!\"\n  }\n}\n&lt;/i18n&gt;</code></pre>\n    \n\n<p>What this means is that you have given a component a value that is different from the value found in the <strong>en.json</strong> file inside the <strong><em>locales</em></strong> folder. In the template section of this component, we have:</p>\n\n<pre><code class=\"language-javascript\">&lt;template&gt;\n  &lt;div&gt;\n    &lt;p&gt;{{ $t(\'hello\') }}&lt;/p&gt;\n  &lt;/div&gt;\n&lt;/template&gt;</code></pre>\n \n\n<p>Here, we see <code>$t(\'\')</code>, this is the syntax for referencing texts(<strong>t</strong> stands for texts) from our plugin, and in this component, we&rsquo;re using the value of <code>hello</code> that we added inside the <code>i18n</code> tag. If we check our browser, we should see <em>Hello i18n in SFC!</em> even if there is no <code>hello</code> property in the <strong>en.json</strong> file. This is called Component-based localization and we would go deeper into it later on in <a href=\"https://www.dropbox.com/scl/fi/83fwmb6d7d6ki9grnpwjs/Internationalization-in-Vue.paper?dl=0&amp;rlkey=p375ayihwuka1bxedf2pfaih9#:uid=985977966247627244079005&amp;h2=Component-Based-localization\">this article</a>.</p>\n\n<h3 id=\"formatting-texts\">Formatting Texts</h3>\n\n<p>This plugin comes with the option to format your texts in different ways which can be helpful in enhancing user experience and we’re going to be looking at some of these formats.</p>\n\n<h4 id=\"named-formatting\">Named Formatting</h4>\n\n<p>This type of format option allows you add a dynamic value inside your text which would be defined when rendering the text in your browser. This type of format is useful when you want to add a personalized text with a user&rsquo;s info on login or after performing an action. To see how that works, we&rsquo;re going to add a new page to our app and call it <strong>formatting.vue</strong>, we&rsquo;re also going to add this as a route in our app.</p>\n\n<p>First, let&rsquo;s create the file and add the following lines of code:</p>\n\n<div class=\"break-out\">\n<pre><code class=\"language-javascript\">&lt;template&gt;\n  &lt;section&gt;\n    &lt;h1&gt;{{$t(\'formattingTitle\')}}&lt;/h1&gt;\n    &lt;p v-show=\"showMessage\"&gt;{{ $t(\'hello\', {name: name}) }}&lt;/p&gt;\n    &lt;form @submit.prevent=\"showMessage = true\"&gt;\n      &lt;label for=\"name\"&gt;{{ $t(\'name\') }}&lt;/label&gt;\n      &lt;input type=\"text\" name=\"name\" id=\"name\" v-model=\"name\" /&gt;\n      &lt;input type=\"submit\" :disabled=\"name.length &lt; 1\" value=\"send\" /&gt;\n      &lt;label for=\"hideMessage\" v-if=\"showMessage\"&gt;\n        &lt;input type=\"checkbox\" name=\"hideMessage\" id=\"hideMessage\" v-model=\"showMessage\" /&gt; Show Message\n      &lt;/label&gt;\n    &lt;/form&gt;\n  &lt;/section&gt;\n&lt;/template&gt;\n&lt;script&gt;\nexport default {\n  data() {\n    return {\n      name: \"\",\n      showMessage: false\n    };\n  }\n};\n&lt;/script&gt;\n&lt;style&gt;\nform {\n  width: 100%;\n  max-width: 300px;\n  margin: 20px auto;\n}\nlabel {\n  display: block;\n  width: 100%;\n  text-align: left;\n  margin-bottom: 5px;\n}\ninput[type=\"text\"] {\n  width: 100%;\n  height: 30px;\n  border-radius: 3px;\n  border: 1px solid #eee;\n  padding-left: 10px;\n  box-sizing: border-box;\n  margin-bottom: 10px;\n}\ninput[type=\"submit\"] {\n  width: 80px;\n  height: 30px;\n  border-radius: 3px;\n  border: 0;\n}\n&lt;/style&gt;</code></pre>\n</div>\n   \n\n<p>In the template section of this file, we make use of this plugin to add a title (which we&rsquo;re yet to add) to this page. Inside the <code>&lt;p&gt;</code> tag, we make use of the named format to add a personalized message for the user which only displays if (<code>v-show</code>) <code>showMessage</code> is true. We have a form with an input field (connected to our data using v-model) that accepts a name that is passed to our plugin when the user submits the form. We have a checkbox that hides the message and a submit button that toggles <code>showMessage</code> to <code>true</code>.</p>\n\n<p>In the script section, we have <code>name</code> and <code>showMessage</code> inside our data. Both of these variables are used in our form to store the user’s input and toggle the message respectively.</p>\n\n<p>Now, let us add this <code>hello</code> to our <strong>en.json</strong> file (your default locale file). This looks like this:</p>\n\n<pre><code class=\"language-javascript\">{\n  \"formattingTitle\": \"How to format your texts\",\n  \"name\": \"What is your Name?\",\n  \"hello\": \"Hi {name}, today is a good day\"\n}</code></pre>\n   \n\n<p>Here, <code>formattingTitle</code> is the title for our formatting page while <code>hello</code> makes use of the name format that we used on the same page.</p>\n\n<p>Finally, let us add this page to our router file. This looks like this:</p>\n\n<div class=\"break-out\">\n<pre><code class=\"language-javascript\">import Vue from \'vue\'\nimport Router from \'vue-router\'\nimport Home from \'./views/Home.vue\'\nVue.use(Router)\nexport default new Router({\n  mode: \'history\',\n  base: process.env.BASE_URL,\n  routes: [{\n      path: \'/\',\n      name: \'home\',\n      component: Home\n    },\n    {\n      path: \'/formatting\',\n      name: \'formatting\',\n      // route level code-splitting\n      // this generates a separate chunk (about.[hash].js) for this route\n      // which is lazy-loaded when the route is visited.\n      component: () =&gt; import( /* webpackChunkName: \"format\" */ \'./views/formatting.vue\')\n    }\n  ]\n})</code></pre>\n</div>\n\n<p>In the router file, we make use of <a href=\"https://router.vuejs.org/guide/advanced/lazy-loading.html\">route level code-splitting</a> to load our component into its route (i.e <code>/formatting</code> ) which is another way of adding a component to a route in Vue.</p>\n\n<p>Now, if we navigate to <code>/formatting</code> in our browser, we should see this:</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/bf285a18-0d4d-4308-a7b6-60dfc75bdaca/04-formatting-landing.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/bf285a18-0d4d-4308-a7b6-60dfc75bdaca/04-formatting-landing.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/bf285a18-0d4d-4308-a7b6-60dfc75bdaca/04-formatting-landing.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/bf285a18-0d4d-4308-a7b6-60dfc75bdaca/04-formatting-landing.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/bf285a18-0d4d-4308-a7b6-60dfc75bdaca/04-formatting-landing.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/bf285a18-0d4d-4308-a7b6-60dfc75bdaca/04-formatting-landing.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/bf285a18-0d4d-4308-a7b6-60dfc75bdaca/04-formatting-landing.png\"\n			sizes=\"100vw\"\n			alt=\"Formatting page with an input field for name.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Current formatting page. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/bf285a18-0d4d-4308-a7b6-60dfc75bdaca/04-formatting-landing.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<p>Now, when you enter a value into the input field and press enter, you would see a personalized text above your form field.</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/5263926c-f473-492c-b4b1-7db13fc2b9ba/05-named-formatting.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/5263926c-f473-492c-b4b1-7db13fc2b9ba/05-named-formatting.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/5263926c-f473-492c-b4b1-7db13fc2b9ba/05-named-formatting.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/5263926c-f473-492c-b4b1-7db13fc2b9ba/05-named-formatting.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/5263926c-f473-492c-b4b1-7db13fc2b9ba/05-named-formatting.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/5263926c-f473-492c-b4b1-7db13fc2b9ba/05-named-formatting.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/5263926c-f473-492c-b4b1-7db13fc2b9ba/05-named-formatting.png\"\n			sizes=\"100vw\"\n			alt=\"Formatting page containing a personalized greeting text with an input field with a name.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Named formatting in action. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/5263926c-f473-492c-b4b1-7db13fc2b9ba/05-named-formatting.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<div class=\"sponsors__lead-place\"></div>\n\n\n\n\n<h4 id=\"html-formatting\">HTML Formatting</h4>\n\n<p>This involves using valid HTML in your text instead of plain text. This can be useful when you’re trying to display HTML formatted text to the user. Let us see how that works in our app.</p>\n\n<p>Add the following to your locale file.</p>\n\n<pre><code class=\"language-javascript\">{\n  \"htmlText\": \"&lt;h1&gt;HTML Rocks ❤❤&lt;/h1&gt;\"\n}</code></pre>\n\n<p>In our <strong>formatting.vue</strong> file, add the following lines of code after your form to the <code>template</code> section of this file.</p>\n\n<pre><code class=\"language-javascript\">&lt;div v-html=\"$t(\'htmlText\')\"&gt;&lt;/div&gt;</code></pre>\n\n<p>Here, we make use of Vue’s <a href=\"https://vuejs.org/v2/guide/syntax.html#Raw-HTML\">HTML directive</a> to bind our text to this <code>div</code>. If you check it out in your browser, you should see the value of <code>htmlText</code> being rendered and if you inspect the div element, you should see the <code>h1</code> element nested inside this div.</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n    break-out article__image\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8ce50f29-d292-4ca1-b302-1d6360103c22/06-html-formatting.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8ce50f29-d292-4ca1-b302-1d6360103c22/06-html-formatting.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8ce50f29-d292-4ca1-b302-1d6360103c22/06-html-formatting.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8ce50f29-d292-4ca1-b302-1d6360103c22/06-html-formatting.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8ce50f29-d292-4ca1-b302-1d6360103c22/06-html-formatting.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8ce50f29-d292-4ca1-b302-1d6360103c22/06-html-formatting.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8ce50f29-d292-4ca1-b302-1d6360103c22/06-html-formatting.png\"\n			sizes=\"100vw\"\n			alt=\"Formatting page with devtools open below it.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Representation of HTML formatting. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8ce50f29-d292-4ca1-b302-1d6360103c22/06-html-formatting.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<h3 id=\"switching-between-locale\">Switching Between Locale</h3>\n\n<p>Switching from one locale to another can be done by adding a file with this format to your locale folder.</p>\n\n<pre><code class=\"language-javascript\">locale abbrevation + json\n//eg en.json, fr.json, ru.json, de.json</code></pre>\n\n<p>After creating this file and adding a text(e.g ‘hello’) we want to use in our app, you can reference a text in that locale in two ways:</p>\n\n<ul>\n<li>Per text:</li>\n</ul>\n\n<pre><code class=\"language-javascript\">&lt;p&gt;{{ $t(\'hello\', \'de\') }} &lt;/p&gt;</code></pre>\n\n<p>This would render <code>hello</code>, but in Deutsch assuming we have it defined in that locale.</p>\n\n<ul>\n<li>Globally using <code>this.$i18n.locale</code>:</li>\n</ul>\n\n<pre><code class=\"language-javascript\">console.log(this.$i18n.locale)\n// prints \'en.json\' because \'en\' is my selected locale\nthis.$i18n.locale = \'de\'\n// sets your locale to \'de\'</code></pre>\n\n<p>Let us add another use case to our application. The first thing we&rsquo;re going to do is add a new file to our locale folder and name it <strong>de.json</strong> then add this line object to the file.</p>\n\n<pre><code class=\"language-javascript\">{\n  \"home\": \"Zuhause\",\n  \"formatting\": \"Formatieren Sie Ihre Texte\",\n  \"formattingTitle\": \"So formatieren Sie Ihre Texte\",\n  \"name\": \"Wie heißen Sie?\",\n  \"hello\": \"Hallo {name}, heute ist ein guter Tag\",\n  \"htmlText\": \"<h1>HTML Rocks ❤❤</h1>\"\n}</code></pre>\n\n<p>We already have the <code>en</code> version of everything here in our <strong>en.json</strong> file but we want to be able to switch between <code>en</code> and <code>de</code> so we add the Deutsch translation of this to our <strong>de.json</strong> file.</p>\n\n<p>The next thing would be to add a button that switches between <code>en</code> and <code>de</code> inside our <strong>formatting.vue</strong> file. Add this to your file:</p>\n\n<div class=\"break-out\">\n<pre><code class=\"language-javascript\">&lt;template&gt;\n  &lt;section&gt;\n    &lt;!-- existing div element --&gt;\n    &lt;div v-html=\"$t(\'htmlText\')\"&gt;&lt;/div&gt;\n    &lt;button @click=\"switchLocale\"&gt;Switch to {{locale}}&lt;/button&gt;\n  &lt;/section&gt;\n&lt;/template&gt;\n&lt;script&gt;\nexport default {\n  data() {\n    return {\n      name: \"\",\n      showMessage: false,\n      locale: \"Deutsch\"\n    };\n  },\n  methods: {\n    switchLocale() {\n      this.$i18n.locale = this.locale === \"English\" ? \"en\" : \"de\";\n      this.locale = this.$i18n.locale === \"en\" ? \"Deutsch\" : \"English\";\n    }\n  }\n};\n&lt;/script&gt;</code></pre>\n</div>\n\n<p>In the template section, we have added a button with a click event that changes the locale from either <code>en</code> to <code>de</code> or vice versa. We also have a <code>locale</code> variable that dynamically changes from <em>English</em> to <em>Deutsch</em>. In the script section, we have added a <code>locale</code> variable to the data function of this component. Finally, we have a <code>switchLocale</code> method that is called whenever a user clicks on the button. This method changes the value of <code>this.$i18n.locale</code> using a <a href=\"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Conditional_Operator\">ternary operator</a> to determine it’s own value between <code>de</code> and <code>en</code> based on what <code>locale</code> is. This means if <code>locale</code> is <em>English</em>, <code>this.$i18n.locale</code> will be <code>en</code> and if <code>this.$i18n.locale</code> is <code>de</code>, <code>locale</code> will be <em>English</em>.</p>\n\n<p>If you view this in your browser, you should see this:</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n    break-out article__image\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/a29a1894-6806-4cf1-aaf8-098eb4e7e066/07-en-locale.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/a29a1894-6806-4cf1-aaf8-098eb4e7e066/07-en-locale.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/a29a1894-6806-4cf1-aaf8-098eb4e7e066/07-en-locale.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/a29a1894-6806-4cf1-aaf8-098eb4e7e066/07-en-locale.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/a29a1894-6806-4cf1-aaf8-098eb4e7e066/07-en-locale.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/a29a1894-6806-4cf1-aaf8-098eb4e7e066/07-en-locale.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/a29a1894-6806-4cf1-aaf8-098eb4e7e066/07-en-locale.png\"\n			sizes=\"100vw\"\n			alt=\"Formatting Page translated in English.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Formatting page in default locale. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/a29a1894-6806-4cf1-aaf8-098eb4e7e066/07-en-locale.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<p>And when you click on the button, you should see that every text on your page; in this component and globally, has changed from the default locale to Deutsch.</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n    break-out article__image\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b830c82b-2316-4dbf-9a5c-6da07f5e4c44/08-de-locale.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b830c82b-2316-4dbf-9a5c-6da07f5e4c44/08-de-locale.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b830c82b-2316-4dbf-9a5c-6da07f5e4c44/08-de-locale.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b830c82b-2316-4dbf-9a5c-6da07f5e4c44/08-de-locale.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b830c82b-2316-4dbf-9a5c-6da07f5e4c44/08-de-locale.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b830c82b-2316-4dbf-9a5c-6da07f5e4c44/08-de-locale.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b830c82b-2316-4dbf-9a5c-6da07f5e4c44/08-de-locale.png\"\n			sizes=\"100vw\"\n			alt=\"Formatting page transalted in Deutsch.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Formatting page in changed locale(de). (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/b830c82b-2316-4dbf-9a5c-6da07f5e4c44/08-de-locale.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<p>If you enter your name and submit the form, you should also see that it has been translated and looks like this:</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/f8733a34-6b5f-4204-9b37-5337475b039f/09-de-locale.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/f8733a34-6b5f-4204-9b37-5337475b039f/09-de-locale.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/f8733a34-6b5f-4204-9b37-5337475b039f/09-de-locale.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/f8733a34-6b5f-4204-9b37-5337475b039f/09-de-locale.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/f8733a34-6b5f-4204-9b37-5337475b039f/09-de-locale.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/f8733a34-6b5f-4204-9b37-5337475b039f/09-de-locale.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/f8733a34-6b5f-4204-9b37-5337475b039f/09-de-locale.png\"\n			sizes=\"100vw\"\n			alt=\"Formatting page with personalized message in Deutsch.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Formatting page with personalized message in Deutsch. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/f8733a34-6b5f-4204-9b37-5337475b039f/09-de-locale.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<h3 id=\"fallback-localization-and-pluralization\">Fallback Localization And Pluralization</h3>\n\n<h4 id=\"fallback-localization\">Fallback Localization</h4>\n\n<p>There are cases where you would not have the value of a property available in a selected locale. Instead of your app crashing as a result, it fetches the value of the text from the default locale and prints a warning error to your console. Let us look at an example.</p>\n\n<p>We&rsquo;re going to add this text to our <strong>en.json</strong> file:</p>\n\n<pre><code class=\"language-javascript\">  {\n  \"fallbackLocale\": \"Fallback Localization\",\n  \"placeholder\": \"This is the fallback text\"\n}</code></pre>\n\n<p>And in our <strong>de.json</strong> file, we&rsquo;re only going to add this:</p>\n\n<pre><code class=\"language-javascript\">{\n  \"fallbackLocale\": \"Fallback-Lokalisierung\"\n}</code></pre>\n\n<p>In our <strong>formatting.vue</strong> file, add this piece of code inside the file:</p>\n\n<pre><code class=\"language-javascript\">&lt;template&gt;\n  &lt;section&gt;\n    &lt;!-- last button --&gt;\n    &lt;button @click=\"switchLocale\"&gt;Switch to {{locale}}&lt;/button&gt;\n    &lt;div&gt;\n      &lt;h1&gt;{{ $t(\'fallbackLocale\') }}&lt;/h1&gt;\n    &lt;/div&gt;\n    \n  &lt;/section&gt;\n&lt;/template&gt;\n&lt;/style&gt;</code></pre>\n\n<p>Here, we have added a text with the property name <code>fallbackLocale</code> inside an <code>h1</code> tag that serves as the heading for this page. We also have a <code>p</code> tag that has a property name <code>placeholder</code> inside the plugin but with another parameter, <code>de</code> which as we’ve seen earlier, is a way of telling the plugin to fetch that property in the specified locale (<code>de</code> in this case).</p>\n\n<p>Now, we should see this in our browser.</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/dc8d3385-27c1-4614-99b6-101efbc6e32e/10-fallback.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/dc8d3385-27c1-4614-99b6-101efbc6e32e/10-fallback.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/dc8d3385-27c1-4614-99b6-101efbc6e32e/10-fallback.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/dc8d3385-27c1-4614-99b6-101efbc6e32e/10-fallback.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/dc8d3385-27c1-4614-99b6-101efbc6e32e/10-fallback.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/dc8d3385-27c1-4614-99b6-101efbc6e32e/10-fallback.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/dc8d3385-27c1-4614-99b6-101efbc6e32e/10-fallback.png\"\n			sizes=\"100vw\"\n			alt=\"formatting page with fallback text.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Formatting page with fallback text. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/dc8d3385-27c1-4614-99b6-101efbc6e32e/10-fallback.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<p>We can notice that although we set <code>placeholder</code> to <code>de</code>, the text displayed is in <code>en</code>. This is because although we have set <code>placeholder</code> to display in another locale, it isn’t translated in the selected locale, and hence, the plugin would display this property in the default locale while printing a warning message to your console.</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n    break-out article__image\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/94c7d25d-97ce-4615-a7a3-5ebf5c7660a3/11-fallback-warning.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/94c7d25d-97ce-4615-a7a3-5ebf5c7660a3/11-fallback-warning.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/94c7d25d-97ce-4615-a7a3-5ebf5c7660a3/11-fallback-warning.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/94c7d25d-97ce-4615-a7a3-5ebf5c7660a3/11-fallback-warning.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/94c7d25d-97ce-4615-a7a3-5ebf5c7660a3/11-fallback-warning.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/94c7d25d-97ce-4615-a7a3-5ebf5c7660a3/11-fallback-warning.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/94c7d25d-97ce-4615-a7a3-5ebf5c7660a3/11-fallback-warning.png\"\n			sizes=\"100vw\"\n			alt=\"Formatting page with fallback warning in devtools console.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Fallback warning in console. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/94c7d25d-97ce-4615-a7a3-5ebf5c7660a3/11-fallback-warning.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<h4 id=\"pluralization\">Pluralization</h4>\n\n<p>This is the process of giving plural form to a word. For instance, you’re building an eCommerce application and you want to render an item in a user’s shopping cart based on the number they have in their cart. You can handle pluralization in your plugin by using a pipe <code>|</code> separator between all the plural forms in your locale.</p>\n\n<p>To see how that works, let us add this to our <strong>en.json</strong> file.</p>\n\n<pre><code class=\"language-javascript\">{\n  \"developer\": \"no developer | one developer | {n} developers\"\n}</code></pre>\n\n<p><em>Note that the variable can be called anything but I have called it <code>n</code>.</em></p>\n\n<p>And in your <strong>formatting.vue</strong> file, instead of using <code>$t(\'\')</code>, we would use <code>$tc(\'\')</code> which also accepts a number as a second parameter ( <code>n</code> which we added in our locale file). So, if we add the following lines of code to our template.</p>\n\n<pre><code class=\"language-javascript\">&lt;p&gt;{{ $tc(\'developer\', 0) }}&lt;/p&gt;\n&lt;p&gt;{{ $tc(\'developer\', 1) }}&lt;/p&gt;\n&lt;p&gt;{{ $tc(\'developer\', 2) }}&lt;/p&gt;</code></pre>\n   \n\n<p>Here, we set the first value for <code>n</code> to be zero, the second one is set to 1 and the last one is set to 2. Let us see what this looks like in our browser.</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/648fef3d-b6c4-4be4-86aa-38f5eb1301af/12-pluralization.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/648fef3d-b6c4-4be4-86aa-38f5eb1301af/12-pluralization.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/648fef3d-b6c4-4be4-86aa-38f5eb1301af/12-pluralization.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/648fef3d-b6c4-4be4-86aa-38f5eb1301af/12-pluralization.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/648fef3d-b6c4-4be4-86aa-38f5eb1301af/12-pluralization.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/648fef3d-b6c4-4be4-86aa-38f5eb1301af/12-pluralization.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/648fef3d-b6c4-4be4-86aa-38f5eb1301af/12-pluralization.png\"\n			sizes=\"100vw\"\n			alt=\"Pluralization of texts on formatting page.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Implementation of pluralization. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/648fef3d-b6c4-4be4-86aa-38f5eb1301af/12-pluralization.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<p>We can see that the plugin has translated each value and used the appropriate plural depending on the value of <code>n</code>.</p>\n\n<p><strong>Recommended reading</strong>: <em><a href=\"https://www.smashingmagazine.com/2014/12/how-to-conduct-website-localization/\">How To Conduct Website Localization: Don’t Get Lost In Translation</a></em></p>\n\n<h3 id=\"component-based-localization\">Component-Based Localization</h3>\n\n<p>There are cases where you’re only going to need some words or sentences in a component alone or instances where a global text has a different meaning in a particular component and in cases like this, component-based localization comes in handy. Component-based localization is the process of translating text/group of texts inside a component thereby making it only available inside such component. One thing we have to note is that the translation available inside your component takes precedence over the global translation so that if for instance, you&rsquo;re using <code>hello</code> in more than one place in your app and you want it to have a longer text or more personalized for a component, you only need to create a localization config for that component and define your new translation of <code>hello</code>.</p>\n\n<p>If we open our <strong>Components</strong> folder, we should see a <strong>Helloi18n.vue</strong> file that was added to our app when we installed the plugin, this component was added to serve as a guide on how component-based localization works.</p>\n\n<p>To understand better, let us add the following translation inside our <code>&lt;i18n&gt;</code> element.</p>\n\n<pre><code class=\"language-javascript\">&lt;i18n&gt;\n{\n  \"en\": {\n    \"hello\": \"Hello, {name}, this is i18n in SFC!\",\n    \"greetings\": \"Component-Based Localization\",\n    \"placeholder\": \"This is a component-based fallback text\"\n  }\n}\n&lt;/i18n&gt;</code></pre>\n\n<p>Here, we add a translation for <code>hello</code>, <code>greetings</code> and <code>placeholder</code>, all of which are also translated in the global <strong>en.json</strong> file.</p>\n\n<p>And in our component, let us add the following:</p>\n\n<div class=\"break-out\">\n<pre><code class=\"language-javascript\">&lt;template&gt;\n  &lt;div&gt;\n    &lt;h1&gt;{{ $t(\"greetings\") }}&lt;/h1&gt;\n    &lt;p v-if=\"name.length &gt; 0\"&gt;{{ $t(\'hello\', {name: name }) }}&lt;/p&gt;\n    &lt;p&gt;{{ $t(\'placeholder\') }}&lt;/p&gt;\n  &lt;/div&gt;\n&lt;/template&gt;\n&lt;script&gt;\nexport default {\n  name: \"HelloI18n\",\n  props: [\"name\"]\n};\n&lt;/script&gt;</code></pre>\n</div>\n\n<p>Here, we have a heading that displays a translated <code>greetings</code> text, a paragraph tag that makes use of named formatting to display a personalized <code>hello</code> text from a <code>name</code> variable that would be passed to the component as a prop.</p>\n\n<p>Finally we’re going to display this component in <strong>formatting.vue</strong>. Let us import it into this file:</p>\n\n<pre><code class=\"language-javascript\">&lt;script&gt;\n// @ is an alias to /src\nimport HelloI18n from \"@/components/HelloI18n.vue\";\nexport default {\n  // existing code\n  components: {\n    HelloI18n\n  }\n};</code></pre>   \n\n<p>Here, we import the <strong>Helloi18n.vue</strong> component using <code>@</code> alias and define it inside the <code>components</code> property of our component.</p>\n\n<p>And add it to our template like this:</p>\n\n<pre><code class=\"language-javascript\">&lt;template&gt;\n  &lt;section&gt;\n    &lt;!-- existing code --&gt;\n    &lt;HelloI18n :name=\"name\" /&gt;\n  &lt;/section&gt;\n&lt;/template&gt;</code></pre>\n \n\n<p>We defined a prop value <code>name</code> inside the <code>Helloi18n</code> component, so we pass it a value of <code>name</code> which we would get from the input field in the <strong>formatting.vue</strong> page.</p>\n\n<p>Now, if we view this page in our browser, we should see this:</p>\n\n\n\n\n\n\n\n\n\n\n\n<figure class=\"\n  \n  \n  \">\n  \n    <a href=\"https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8af9e3e0-fd32-40fb-b4be-458978d399b6/13-component.png\">\n    \n    <img\n			srcset=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8af9e3e0-fd32-40fb-b4be-458978d399b6/13-component.png 400w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_800/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8af9e3e0-fd32-40fb-b4be-458978d399b6/13-component.png 800w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1200/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8af9e3e0-fd32-40fb-b4be-458978d399b6/13-component.png 1200w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_1600/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8af9e3e0-fd32-40fb-b4be-458978d399b6/13-component.png 1600w,\n			        https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_2000/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8af9e3e0-fd32-40fb-b4be-458978d399b6/13-component.png 2000w\"\n			src=\"https://res.cloudinary.com/indysigner/image/fetch/f_auto,q_auto/w_400/https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8af9e3e0-fd32-40fb-b4be-458978d399b6/13-component.png\"\n			sizes=\"100vw\"\n			alt=\"Component-based localization.\"\n		/>\n    \n    </a>\n  \n\n  \n    <figcaption class=\"op-vertical-bottom\">\n      Component-based localization. (<a href=\'https://cloud.netlifyusercontent.com/assets/344dbf88-fdf9-42bb-adb4-46f01eedd629/8af9e3e0-fd32-40fb-b4be-458978d399b6/13-component.png\'>Large preview</a>)\n    </figcaption>\n  \n</figure>\n\n<p>We can see that although we&rsquo;re using the same <code>greetings</code>, <code>hello</code> and <code>placeholder</code> text from the global translation file, the translation in the component is exactly what we defined inside the <code>&lt;i18n&gt;</code> tag.</p>\n\n<h3 id=\"conclusion\">Conclusion</h3>\n\n<p>The <em>Vue I18n</em> plugin has a lot of use cases like:</p>\n\n<ul>\n<li>DataTime localization,</li>\n<li>Number localization,</li>\n<li>Locale message syntax,</li>\n<li>Lazy-loading translation, and so on.</li>\n</ul>\n\n<p>All of which help in completely achieving internationalization of your application, so I would recommend you go through the full documentation and play around with some of them to get yourself familiarized with them.</p>\n\n<h3 id=\"resources\">Resources</h3>\n\n<ul>\n<li>“<a href=\"https://lingoport.com/what-is-i18n/\">What Is i18n?</a>,” Lingoport</li>\n<li>“<a href=\"https://whatis.techtarget.com/definition/internationalization-I18N\">internationalization (I18N)</a>,” Margaret Rouse, WhatIs.com</li>\n<li>“<a href=\"https://kazupon.github.io/vue-i18n/\">Vue I18n</a>,” an internationalization plugin for Vue.js created by Kazuya Kawaguchi</li>\n</ul>\n\n<div class=\"signature\">\n  <img src=\"https://www.smashingmagazine.com/images/logo/logo--red.png\" alt=\"Smashing Editorial\">\n  <span>(ks, ra, yk, il)</span>\n</div>\n\n\n              </article>\n            </body>\n          </html>\n        ', 'Recent content in Articles on Smashing Magazine — For Web Designers And Developers', 'basic_html');
